// ApiTokenScoped reaches ApiToken entities of one Workspace.
type ApiTokenScoped struct{ s *Scoped }

// ApiToken returns the ApiToken entities of the Workspace.
func (s *Scoped) ApiToken() *ApiTokenScoped { return &ApiTokenScoped{s: s} }

const (
	TypeOf_ApiTokenScoped             = TypeWrapper
	EntityOf_ApiTokenScoped           = "ApiToken"
	RoleOf_Scoped_ApiToken            = RoleNone
	RoleOf_ApiTokenScoped_Query       = RoleRead
	RoleOf_ApiTokenScoped_Get         = RoleRead
	RoleOf_ApiTokenScoped_DeleteOneID = RoleStart
	RoleOf_ApiTokenScoped_UpdateOneID = RoleStart
	RoleOf_ApiTokenScoped_Delete      = RoleStart
	RoleOf_ApiTokenScoped_Create      = RoleStart
	RoleOf_ApiTokenScoped_CreateBulk  = RoleStart
	RoleOf_ApiTokenScoped_Update      = RoleStart
)

// inApiToken confines predicates of ApiToken rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inApiToken(ps ...predicate.ApiToken) []predicate.ApiToken {
	return append([]predicate.ApiToken{apitoken.WorkspaceID(s.ws)}, ps...)
}

// Query returns a ApiToken query already confined to the Workspace.
func (t *ApiTokenScoped) Query() *ApiTokenQuery {
	return t.s.c.ApiToken.Query().Where(t.s.inApiToken()...)
}

// Get returns the ApiToken with the id; a row of another Workspace is not found.
func (t *ApiTokenScoped) Get(ctx context.Context, id int64) (*ApiToken, error) {
	return t.Query().Where(apitoken.ID(id)).Only(ctx)
}

// writeApiToken runs a write of ApiToken rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeApiToken(ctx context.Context, verb string, where []predicate.ApiToken, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*ApiToken
			if where != nil {
				var err error
				if before, err = ts.c.ApiToken.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*ApiToken, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.ApiToken.Query().Where(apitoken.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*ApiToken, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeApiToken(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkApiToken verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkApiToken(ctx context.Context, ms ...*ApiTokenMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.MembershipIDs()...)
		}
		if err := s.verifyMembership(ctx, ids); err != nil {
			return fmt.Errorf("membership: %w", err)
		}
	}
	return nil
}

// ApiTokenScopedDeleteOne deletes one ApiToken: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type ApiTokenScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.ApiToken
}

// DeleteOneID deletes the ApiToken with the id; a row of another Workspace is not found.
func (t *ApiTokenScoped) DeleteOneID(id int64) *ApiTokenScopedDeleteOne {
	return &ApiTokenScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *ApiTokenScopedDeleteOne) Where(ps ...predicate.ApiToken) *ApiTokenScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_ApiTokenScopedDeleteOne       = TypeScopedDelete
	EntityOf_ApiTokenScopedDeleteOne     = "ApiToken"
	RoleOf_ApiTokenScopedDeleteOne_Where = RoleStep
	RoleOf_ApiTokenScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *ApiTokenScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inApiToken(x.where...)
	return x.s.writeApiToken(ctx, "delete", append([]predicate.ApiToken{apitoken.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.ApiToken.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// ApiTokenScopedDelete deletes the ApiToken rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type ApiTokenScopedDelete struct {
	s     *Scoped
	where []predicate.ApiToken
}

// Delete deletes the ApiToken entities of the Workspace that match the predicates.
func (t *ApiTokenScoped) Delete() *ApiTokenScopedDelete {
	return &ApiTokenScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *ApiTokenScopedDelete) Where(ps ...predicate.ApiToken) *ApiTokenScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_ApiTokenScopedDelete       = TypeScopedDelete
	EntityOf_ApiTokenScopedDelete     = "ApiToken"
	RoleOf_ApiTokenScopedDelete_Where = RoleStep
	RoleOf_ApiTokenScopedDelete_Exec  = RoleStep
)

// Exec deletes the rows and returns how many were deleted.
func (x *ApiTokenScopedDelete) Exec(ctx context.Context) (int, error) {
	where := x.s.inApiToken(x.where...)
	var n int
	err := x.s.writeApiToken(ctx, "delete", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		var err error
		n, err = s.c.ApiToken.Delete().Where(where...).Exec(ctx)
		return nil, err
	})
	return written(n, err)
}

