// Save verifies the references against the Workspace, then creates the ApiToken.
func (x *ApiTokenScopedCreate) Save(ctx context.Context) (*ApiToken, error) {
	var created *ApiToken
	err := x.s.writeApiToken(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *ApiTokenScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// ApiTokenScopedCreateBulk creates several ApiToken entities of one Workspace at once.
type ApiTokenScopedCreateBulk struct {
	s  *Scoped
	xs []*ApiTokenScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ApiTokenScoped) CreateBulk(xs ...*ApiTokenScopedCreate) *ApiTokenScopedCreateBulk {
	return &ApiTokenScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *ApiTokenScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("ApiToken: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *ApiTokenScopedCreateBulk) build(ctx context.Context, s *Scoped) (*ApiTokenCreateBulk, error) {
	builders := make([]*ApiTokenCreate, len(b.xs))
	ms := make([]*ApiTokenMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkApiToken(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.ApiToken.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the ApiToken entities.
func (b *ApiTokenScopedCreateBulk) Save(ctx context.Context) ([]*ApiToken, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*ApiToken
	err := b.s.writeApiToken(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

