// inAuditEntry confines predicates of AuditEntry rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inAuditEntry(ps ...predicate.AuditEntry) []predicate.AuditEntry {
	return append([]predicate.AuditEntry{auditentry.WorkspaceID(s.ws)}, ps...)
}

// Query returns a AuditEntry query already confined to the Workspace.
func (t *AuditEntryScoped) Query() *AuditEntryQuery {
	return t.s.c.AuditEntry.Query().Where(t.s.inAuditEntry()...)
}

// Get returns the AuditEntry with the id; a row of another Workspace is not found.
func (t *AuditEntryScoped) Get(ctx context.Context, id int64) (*AuditEntry, error) {
	return t.Query().Where(auditentry.ID(id)).Only(ctx)
}

// writeAuditEntry runs a write of AuditEntry rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeAuditEntry(ctx context.Context, verb string, where []predicate.AuditEntry, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkAuditEntry verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkAuditEntry(ctx context.Context, ms ...*AuditEntryMutation) error {
	return nil
}

// AuditEntryScopedDeleteOne deletes one AuditEntry: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type AuditEntryScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.AuditEntry
}

// DeleteOneID deletes the AuditEntry with the id; a row of another Workspace is not found.
func (t *AuditEntryScoped) DeleteOneID(id int64) *AuditEntryScopedDeleteOne {
	return &AuditEntryScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *AuditEntryScopedDeleteOne) Where(ps ...predicate.AuditEntry) *AuditEntryScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_AuditEntryScopedDeleteOne       = TypeScopedDelete
	EntityOf_AuditEntryScopedDeleteOne     = "AuditEntry"
	RoleOf_AuditEntryScopedDeleteOne_Where = RoleStep
	RoleOf_AuditEntryScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *AuditEntryScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inAuditEntry(x.where...)
	return x.s.writeAuditEntry(ctx, "delete", append([]predicate.AuditEntry{auditentry.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.AuditEntry.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

