// Save verifies the references against the Workspace, then creates the AuditEntry.
func (x *AuditEntryScopedCreate) Save(ctx context.Context) (*AuditEntry, error) {
	var created *AuditEntry
	err := x.s.writeAuditEntry(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *AuditEntryScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// AuditEntryScopedCreateBulk creates several AuditEntry entities of one Workspace at once.
type AuditEntryScopedCreateBulk struct {
	s  *Scoped
	xs []*AuditEntryScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AuditEntryScoped) CreateBulk(xs ...*AuditEntryScopedCreate) *AuditEntryScopedCreateBulk {
	return &AuditEntryScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *AuditEntryScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("AuditEntry: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *AuditEntryScopedCreateBulk) build(ctx context.Context, s *Scoped) (*AuditEntryCreateBulk, error) {
	builders := make([]*AuditEntryCreate, len(b.xs))
	ms := make([]*AuditEntryMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkAuditEntry(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.AuditEntry.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the AuditEntry entities.
func (b *AuditEntryScopedCreateBulk) Save(ctx context.Context) ([]*AuditEntry, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*AuditEntry
	err := b.s.writeAuditEntry(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *AuditEntryScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

