// Save verifies the references against the Workspace, then creates the Automation.
func (x *AutomationScopedCreate) Save(ctx context.Context) (*Automation, error) {
	var created *Automation
	err := x.s.writeAutomation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *AutomationScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// AutomationScopedCreateBulk creates several Automation entities of one Workspace at once.
type AutomationScopedCreateBulk struct {
	s  *Scoped
	xs []*AutomationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AutomationScoped) CreateBulk(xs ...*AutomationScopedCreate) *AutomationScopedCreateBulk {
	return &AutomationScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *AutomationScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Automation: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *AutomationScopedCreateBulk) build(ctx context.Context, s *Scoped) (*AutomationCreateBulk, error) {
	builders := make([]*AutomationCreate, len(b.xs))
	ms := make([]*AutomationMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkAutomation(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Automation.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Automation entities.
func (b *AutomationScopedCreateBulk) Save(ctx context.Context) ([]*Automation, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Automation
	err := b.s.writeAutomation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *AutomationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_AutomationScopedCreateBulk                   = TypeScopedCreate
	EntityOf_AutomationScopedCreateBulk                 = "Automation"
	RoleOf_AutomationScopedCreateBulk_Save              = RoleStep
	RoleOf_AutomationScopedCreateBulk_Exec              = RoleStep
	RoleOf_AutomationScopedCreateBulk_OnConflictColumns = RoleStart
)

