// Save verifies the references against the Workspace, then creates the AutomationFigure.
func (x *AutomationFigureScopedCreate) Save(ctx context.Context) (*AutomationFigure, error) {
	var created *AutomationFigure
	err := x.s.writeAutomationFigure(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *AutomationFigureScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// AutomationFigureScopedCreateBulk creates several AutomationFigure entities of one Workspace at once.
type AutomationFigureScopedCreateBulk struct {
	s  *Scoped
	xs []*AutomationFigureScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AutomationFigureScoped) CreateBulk(xs ...*AutomationFigureScopedCreate) *AutomationFigureScopedCreateBulk {
	return &AutomationFigureScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *AutomationFigureScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("AutomationFigure: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *AutomationFigureScopedCreateBulk) build(ctx context.Context, s *Scoped) (*AutomationFigureCreateBulk, error) {
	builders := make([]*AutomationFigureCreate, len(b.xs))
	ms := make([]*AutomationFigureMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkAutomationFigure(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.AutomationFigure.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the AutomationFigure entities.
func (b *AutomationFigureScopedCreateBulk) Save(ctx context.Context) ([]*AutomationFigure, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*AutomationFigure
	err := b.s.writeAutomationFigure(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

