// Save verifies the references against the Workspace, then creates the AutomationRun.
func (x *AutomationRunScopedCreate) Save(ctx context.Context) (*AutomationRun, error) {
	var created *AutomationRun
	err := x.s.writeAutomationRun(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *AutomationRunScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// AutomationRunScopedCreateBulk creates several AutomationRun entities of one Workspace at once.
type AutomationRunScopedCreateBulk struct {
	s  *Scoped
	xs []*AutomationRunScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AutomationRunScoped) CreateBulk(xs ...*AutomationRunScopedCreate) *AutomationRunScopedCreateBulk {
	return &AutomationRunScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *AutomationRunScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("AutomationRun: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *AutomationRunScopedCreateBulk) build(ctx context.Context, s *Scoped) (*AutomationRunCreateBulk, error) {
	builders := make([]*AutomationRunCreate, len(b.xs))
	ms := make([]*AutomationRunMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkAutomationRun(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.AutomationRun.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the AutomationRun entities.
func (b *AutomationRunScopedCreateBulk) Save(ctx context.Context) ([]*AutomationRun, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*AutomationRun
	err := b.s.writeAutomationRun(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *AutomationRunScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

