// Get returns the AutomationVersion with the id; a row of another Workspace is not found.
func (t *AutomationVersionScoped) Get(ctx context.Context, id int64) (*AutomationVersion, error) {
	return t.Query().Where(automationversion.ID(id)).Only(ctx)
}

// writeAutomationVersion runs a write of AutomationVersion rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeAutomationVersion(ctx context.Context, verb string, where []predicate.AutomationVersion, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkAutomationVersion verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkAutomationVersion(ctx context.Context, ms ...*AutomationVersionMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.AutomationIDs()...)
		}
		if err := s.verifyAutomation(ctx, ids); err != nil {
			return fmt.Errorf("automation: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.RunsIDs()...)
		}
		if err := s.verifyAutomationRun(ctx, ids); err != nil {
			return fmt.Errorf("runs: %w", err)
		}
	}
	return nil
}

