// AutomationVersionScopedCreateBulk creates several AutomationVersion entities of one Workspace at once.
type AutomationVersionScopedCreateBulk struct {
	s  *Scoped
	xs []*AutomationVersionScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *AutomationVersionScoped) CreateBulk(xs ...*AutomationVersionScopedCreate) *AutomationVersionScopedCreateBulk {
	return &AutomationVersionScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *AutomationVersionScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("AutomationVersion: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *AutomationVersionScopedCreateBulk) build(ctx context.Context, s *Scoped) (*AutomationVersionCreateBulk, error) {
	builders := make([]*AutomationVersionCreate, len(b.xs))
	ms := make([]*AutomationVersionMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkAutomationVersion(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.AutomationVersion.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the AutomationVersion entities.
func (b *AutomationVersionScopedCreateBulk) Save(ctx context.Context) ([]*AutomationVersion, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*AutomationVersion
	err := b.s.writeAutomationVersion(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *AutomationVersionScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

