func (x *AutomationVersionScopedUpdate) SetUpdatedAt(v time.Time) *AutomationVersionScopedUpdate {
	x.set = append(x.set, func(b *AutomationVersionUpdate) { b.SetUpdatedAt(v) })
	return x
}

