// Save verifies the references against the Workspace, then creates the Binding.
func (x *BindingScopedCreate) Save(ctx context.Context) (*Binding, error) {
	var created *Binding
	err := x.s.writeBinding(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *BindingScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// BindingScopedCreateBulk creates several Binding entities of one Workspace at once.
type BindingScopedCreateBulk struct {
	s  *Scoped
	xs []*BindingScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *BindingScoped) CreateBulk(xs ...*BindingScopedCreate) *BindingScopedCreateBulk {
	return &BindingScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *BindingScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Binding: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *BindingScopedCreateBulk) build(ctx context.Context, s *Scoped) (*BindingCreateBulk, error) {
	builders := make([]*BindingCreate, len(b.xs))
	ms := make([]*BindingMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkBinding(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Binding.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Binding entities.
func (b *BindingScopedCreateBulk) Save(ctx context.Context) ([]*Binding, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Binding
	err := b.s.writeBinding(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *BindingScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_BindingScopedCreateBulk                   = TypeScopedCreate
	EntityOf_BindingScopedCreateBulk                 = "Binding"
	RoleOf_BindingScopedCreateBulk_Save              = RoleStep
	RoleOf_BindingScopedCreateBulk_Exec              = RoleStep
	RoleOf_BindingScopedCreateBulk_OnConflictColumns = RoleStart
)

