func (x *BrandKitScopedCreate) Save(ctx context.Context) (*BrandKit, error) {
	var created *BrandKit
	err := x.s.writeBrandKit(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *BrandKitScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// BrandKitScopedCreateBulk creates several BrandKit entities of one Workspace at once.
type BrandKitScopedCreateBulk struct {
	s  *Scoped
	xs []*BrandKitScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *BrandKitScoped) CreateBulk(xs ...*BrandKitScopedCreate) *BrandKitScopedCreateBulk {
	return &BrandKitScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *BrandKitScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("BrandKit: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *BrandKitScopedCreateBulk) build(ctx context.Context, s *Scoped) (*BrandKitCreateBulk, error) {
	builders := make([]*BrandKitCreate, len(b.xs))
	ms := make([]*BrandKitMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkBrandKit(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.BrandKit.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the BrandKit entities.
func (b *BrandKitScopedCreateBulk) Save(ctx context.Context) ([]*BrandKit, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*BrandKit
	err := b.s.writeBrandKit(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *BrandKitScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

