// Save verifies the references against the Workspace, then creates the Broadcast.
func (x *BroadcastScopedCreate) Save(ctx context.Context) (*Broadcast, error) {
	var created *Broadcast
	err := x.s.writeBroadcast(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *BroadcastScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// BroadcastScopedCreateBulk creates several Broadcast entities of one Workspace at once.
type BroadcastScopedCreateBulk struct {
	s  *Scoped
	xs []*BroadcastScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *BroadcastScoped) CreateBulk(xs ...*BroadcastScopedCreate) *BroadcastScopedCreateBulk {
	return &BroadcastScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *BroadcastScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Broadcast: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *BroadcastScopedCreateBulk) build(ctx context.Context, s *Scoped) (*BroadcastCreateBulk, error) {
	builders := make([]*BroadcastCreate, len(b.xs))
	ms := make([]*BroadcastMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkBroadcast(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Broadcast.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Broadcast entities.
func (b *BroadcastScopedCreateBulk) Save(ctx context.Context) ([]*Broadcast, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Broadcast
	err := b.s.writeBroadcast(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *BroadcastScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

