// Save verifies the references against the Workspace, then creates the BroadcastRecipient.
func (x *BroadcastRecipientScopedCreate) Save(ctx context.Context) (*BroadcastRecipient, error) {
	var created *BroadcastRecipient
	err := x.s.writeBroadcastRecipient(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *BroadcastRecipientScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// BroadcastRecipientScopedCreateBulk creates several BroadcastRecipient entities of one Workspace at once.
type BroadcastRecipientScopedCreateBulk struct {
	s  *Scoped
	xs []*BroadcastRecipientScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *BroadcastRecipientScoped) CreateBulk(xs ...*BroadcastRecipientScopedCreate) *BroadcastRecipientScopedCreateBulk {
	return &BroadcastRecipientScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *BroadcastRecipientScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("BroadcastRecipient: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *BroadcastRecipientScopedCreateBulk) build(ctx context.Context, s *Scoped) (*BroadcastRecipientCreateBulk, error) {
	builders := make([]*BroadcastRecipientCreate, len(b.xs))
	ms := make([]*BroadcastRecipientMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkBroadcastRecipient(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.BroadcastRecipient.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the BroadcastRecipient entities.
func (b *BroadcastRecipientScopedCreateBulk) Save(ctx context.Context) ([]*BroadcastRecipient, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*BroadcastRecipient
	err := b.s.writeBroadcastRecipient(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *BroadcastRecipientScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

