func (x *BroadcastRecipientScopedUpdate) SetUpdatedAt(v time.Time) *BroadcastRecipientScopedUpdate {
	x.set = append(x.set, func(b *BroadcastRecipientUpdate) { b.SetUpdatedAt(v) })
	return x
}

