// CapturedMessageScoped reaches CapturedMessage entities of one Workspace.
type CapturedMessageScoped struct{ s *Scoped }

// CapturedMessage returns the CapturedMessage entities of the Workspace.
func (s *Scoped) CapturedMessage() *CapturedMessageScoped { return &CapturedMessageScoped{s: s} }

const (
	TypeOf_CapturedMessageScoped             = TypeWrapper
	EntityOf_CapturedMessageScoped           = "CapturedMessage"
	RoleOf_Scoped_CapturedMessage            = RoleNone
	RoleOf_CapturedMessageScoped_Query       = RoleRead
	RoleOf_CapturedMessageScoped_Get         = RoleRead
	RoleOf_CapturedMessageScoped_DeleteOneID = RoleStart
	RoleOf_CapturedMessageScoped_UpdateOneID = RoleStart
	RoleOf_CapturedMessageScoped_Delete      = RoleStart
	RoleOf_CapturedMessageScoped_Create      = RoleStart
	RoleOf_CapturedMessageScoped_CreateBulk  = RoleStart
	RoleOf_CapturedMessageScoped_Update      = RoleStart
)

// inCapturedMessage confines predicates of CapturedMessage rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inCapturedMessage(ps ...predicate.CapturedMessage) []predicate.CapturedMessage {
	return append([]predicate.CapturedMessage{capturedmessage.WorkspaceID(s.ws)}, ps...)
}

// Query returns a CapturedMessage query already confined to the Workspace.
func (t *CapturedMessageScoped) Query() *CapturedMessageQuery {
	return t.s.c.CapturedMessage.Query().Where(t.s.inCapturedMessage()...)
}

// Get returns the CapturedMessage with the id; a row of another Workspace is not found.
func (t *CapturedMessageScoped) Get(ctx context.Context, id int64) (*CapturedMessage, error) {
	return t.Query().Where(capturedmessage.ID(id)).Only(ctx)
}

// writeCapturedMessage runs a write of CapturedMessage rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeCapturedMessage(ctx context.Context, verb string, where []predicate.CapturedMessage, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkCapturedMessage verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkCapturedMessage(ctx context.Context, ms ...*CapturedMessageMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.IntegrationIDs()...)
		}
		if err := s.verifyIntegration(ctx, ids); err != nil {
			return fmt.Errorf("integration: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.OutboundMessageIDs()...)
		}
		if err := s.verifyOutboundMessage(ctx, ids); err != nil {
			return fmt.Errorf("outbound_message: %w", err)
		}
	}
	return nil
}

// CapturedMessageScopedDeleteOne deletes one CapturedMessage: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type CapturedMessageScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.CapturedMessage
}

// DeleteOneID deletes the CapturedMessage with the id; a row of another Workspace is not found.
func (t *CapturedMessageScoped) DeleteOneID(id int64) *CapturedMessageScopedDeleteOne {
	return &CapturedMessageScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *CapturedMessageScopedDeleteOne) Where(ps ...predicate.CapturedMessage) *CapturedMessageScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_CapturedMessageScopedDeleteOne       = TypeScopedDelete
	EntityOf_CapturedMessageScopedDeleteOne     = "CapturedMessage"
	RoleOf_CapturedMessageScopedDeleteOne_Where = RoleStep
	RoleOf_CapturedMessageScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *CapturedMessageScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inCapturedMessage(x.where...)
	return x.s.writeCapturedMessage(ctx, "delete", append([]predicate.CapturedMessage{capturedmessage.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.CapturedMessage.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// CapturedMessageScopedDelete deletes the CapturedMessage rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type CapturedMessageScopedDelete struct {
	s     *Scoped
	where []predicate.CapturedMessage
}

// Delete deletes the CapturedMessage entities of the Workspace that match the predicates.
func (t *CapturedMessageScoped) Delete() *CapturedMessageScopedDelete {
	return &CapturedMessageScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
