// Save verifies the references against the Workspace, then creates the CapturedMessage.
func (x *CapturedMessageScopedCreate) Save(ctx context.Context) (*CapturedMessage, error) {
	var created *CapturedMessage
	err := x.s.writeCapturedMessage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *CapturedMessageScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// CapturedMessageScopedCreateBulk creates several CapturedMessage entities of one Workspace at once.
type CapturedMessageScopedCreateBulk struct {
	s  *Scoped
	xs []*CapturedMessageScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *CapturedMessageScoped) CreateBulk(xs ...*CapturedMessageScopedCreate) *CapturedMessageScopedCreateBulk {
	return &CapturedMessageScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *CapturedMessageScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("CapturedMessage: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *CapturedMessageScopedCreateBulk) build(ctx context.Context, s *Scoped) (*CapturedMessageCreateBulk, error) {
	builders := make([]*CapturedMessageCreate, len(b.xs))
	ms := make([]*CapturedMessageMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkCapturedMessage(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.CapturedMessage.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the CapturedMessage entities.
func (b *CapturedMessageScopedCreateBulk) Save(ctx context.Context) ([]*CapturedMessage, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*CapturedMessage
	err := b.s.writeCapturedMessage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *CapturedMessageScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

