// Save verifies the references against the Workspace, then creates the Confirmation.
func (x *ConfirmationScopedCreate) Save(ctx context.Context) (*Confirmation, error) {
	var created *Confirmation
	err := x.s.writeConfirmation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *ConfirmationScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// ConfirmationScopedCreateBulk creates several Confirmation entities of one Workspace at once.
type ConfirmationScopedCreateBulk struct {
	s  *Scoped
	xs []*ConfirmationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ConfirmationScoped) CreateBulk(xs ...*ConfirmationScopedCreate) *ConfirmationScopedCreateBulk {
	return &ConfirmationScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *ConfirmationScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Confirmation: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *ConfirmationScopedCreateBulk) build(ctx context.Context, s *Scoped) (*ConfirmationCreateBulk, error) {
	builders := make([]*ConfirmationCreate, len(b.xs))
	ms := make([]*ConfirmationMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkConfirmation(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Confirmation.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Confirmation entities.
func (b *ConfirmationScopedCreateBulk) Save(ctx context.Context) ([]*Confirmation, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Confirmation
	err := b.s.writeConfirmation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *ConfirmationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

