// DeleteOneID deletes the Contact with the id; a row of another Workspace is not found.
func (t *ContactScoped) DeleteOneID(id int64) *ContactScopedDeleteOne {
	return &ContactScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *ContactScopedDeleteOne) Where(ps ...predicate.Contact) *ContactScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_ContactScopedDeleteOne       = TypeScopedDelete
	EntityOf_ContactScopedDeleteOne     = "Contact"
	RoleOf_ContactScopedDeleteOne_Where = RoleStep
	RoleOf_ContactScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *ContactScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inContact(x.where...)
	return x.s.writeContact(ctx, "delete", append([]predicate.Contact{contact.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.Contact.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// ContactScopedDelete deletes the Contact rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type ContactScopedDelete struct {
	s     *Scoped
	where []predicate.Contact
}

// Delete deletes the Contact entities of the Workspace that match the predicates.
func (t *ContactScoped) Delete() *ContactScopedDelete {
	return &ContactScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *ContactScopedDelete) Where(ps ...predicate.Contact) *ContactScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_ContactScopedDelete       = TypeScopedDelete
	EntityOf_ContactScopedDelete     = "Contact"
	RoleOf_ContactScopedDelete_Where = RoleStep
	RoleOf_ContactScopedDelete_Exec  = RoleStep
)

// Exec deletes the rows and returns how many were deleted.
func (x *ContactScopedDelete) Exec(ctx context.Context) (int, error) {
	where := x.s.inContact(x.where...)
	var n int
	err := x.s.writeContact(ctx, "delete", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		var err error
		n, err = s.c.Contact.Delete().Where(where...).Exec(ctx)
		return nil, err
	})
	return written(n, err)
}

