// Save verifies the references against the Workspace, then updates the Contact.
func (x *ContactScopedUpdateOne) Save(ctx context.Context) (*Contact, error) {
	return x.save(ctx, "update", skipUnchanged)
}

// build makes the ent update on the client of s and verifies the references it sets.
func (x *ContactScopedUpdateOne) build(ctx context.Context, s *Scoped) (*ContactUpdateOne, error) {
	b := s.c.Contact.UpdateOneID(x.id).Where(s.inContact(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkContact(ctx, b.Mutation()))
}

// save is Save under a verb, doing with an unchanged row what unchanged says.
func (x *ContactScopedUpdateOne) save(ctx context.Context, verb string, unchanged unchangedRows) (*Contact, error) {
	where := x.s.inContact(x.where...)
	var updated *Contact
	err := x.s.writeContact(ctx, verb, append([]predicate.Contact{contact.ID(x.id)}, where...), unchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		updated, err = b.Save(ctx)
		return nil, err
	})
	return written(updated, err)
}

// Exec is like Save, discarding the entity.
func (x *ContactScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_ContactScopedUpdateOne       = TypeScopedUpdate
	EntityOf_ContactScopedUpdateOne     = "Contact"
	RoleOf_ContactScopedUpdateOne_Where = RoleStep
	RoleOf_ContactScopedUpdateOne_Save  = RoleStep
	RoleOf_ContactScopedUpdateOne_Exec  = RoleStep
)

// ContactScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type ContactScopedUpdate struct {
	s     *Scoped
	where []predicate.Contact
	set   []func(*ContactUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Contact entities of the Workspace that match the predicates.
func (t *ContactScoped) Update() *ContactScopedUpdate {
	return &ContactScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *ContactScopedUpdate) Where(ps ...predicate.Contact) *ContactScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *ContactScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *ContactScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(contact.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *ContactUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

