// Save verifies the references against the Workspace, then creates the ContactTag.
func (x *ContactTagScopedCreate) Save(ctx context.Context) (*ContactTag, error) {
	var created *ContactTag
	err := x.s.writeContactTag(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *ContactTagScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// ContactTagScopedCreateBulk creates several ContactTag entities of one Workspace at once.
type ContactTagScopedCreateBulk struct {
	s  *Scoped
	xs []*ContactTagScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ContactTagScoped) CreateBulk(xs ...*ContactTagScopedCreate) *ContactTagScopedCreateBulk {
	return &ContactTagScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *ContactTagScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("ContactTag: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *ContactTagScopedCreateBulk) build(ctx context.Context, s *Scoped) (*ContactTagCreateBulk, error) {
	builders := make([]*ContactTagCreate, len(b.xs))
	ms := make([]*ContactTagMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkContactTag(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.ContactTag.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the ContactTag entities.
func (b *ContactTagScopedCreateBulk) Save(ctx context.Context) ([]*ContactTag, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*ContactTag
	err := b.s.writeContactTag(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *ContactTagScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

