func (s *Scoped) CustomField() *CustomFieldScoped { return &CustomFieldScoped{s: s} }

const (
	TypeOf_CustomFieldScoped             = TypeWrapper
	EntityOf_CustomFieldScoped           = "CustomField"
	RoleOf_Scoped_CustomField            = RoleNone
	RoleOf_CustomFieldScoped_Query       = RoleRead
	RoleOf_CustomFieldScoped_Get         = RoleRead
	RoleOf_CustomFieldScoped_DeleteOneID = RoleStart
	RoleOf_CustomFieldScoped_UpdateOneID = RoleStart
	RoleOf_CustomFieldScoped_Delete      = RoleStart
	RoleOf_CustomFieldScoped_Create      = RoleStart
	RoleOf_CustomFieldScoped_CreateBulk  = RoleStart
	RoleOf_CustomFieldScoped_Update      = RoleStart
)

// inCustomField confines predicates of CustomField rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inCustomField(ps ...predicate.CustomField) []predicate.CustomField {
	return append([]predicate.CustomField{customfield.WorkspaceID(s.ws)}, ps...)
}

// Query returns a CustomField query already confined to the Workspace.
func (t *CustomFieldScoped) Query() *CustomFieldQuery {
	return t.s.c.CustomField.Query().Where(t.s.inCustomField()...)
}

// Get returns the CustomField with the id; a row of another Workspace is not found.
func (t *CustomFieldScoped) Get(ctx context.Context, id int64) (*CustomField, error) {
	return t.Query().Where(customfield.ID(id)).Only(ctx)
}

// writeCustomField runs a write of CustomField rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeCustomField(ctx context.Context, verb string, where []predicate.CustomField, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*CustomField
			if where != nil {
				var err error
				if before, err = ts.c.CustomField.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*CustomField, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.CustomField.Query().Where(customfield.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*CustomField, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeCustomField(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkCustomField verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkCustomField(ctx context.Context, ms ...*CustomFieldMutation) error {
	return nil
}

