// CustomFieldScopedCreateBulk creates several CustomField entities of one Workspace at once.
type CustomFieldScopedCreateBulk struct {
	s  *Scoped
	xs []*CustomFieldScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *CustomFieldScoped) CreateBulk(xs ...*CustomFieldScopedCreate) *CustomFieldScopedCreateBulk {
	return &CustomFieldScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *CustomFieldScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("CustomField: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *CustomFieldScopedCreateBulk) build(ctx context.Context, s *Scoped) (*CustomFieldCreateBulk, error) {
	builders := make([]*CustomFieldCreate, len(b.xs))
	ms := make([]*CustomFieldMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkCustomField(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.CustomField.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the CustomField entities.
func (b *CustomFieldScopedCreateBulk) Save(ctx context.Context) ([]*CustomField, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*CustomField
	err := b.s.writeCustomField(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *CustomFieldScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

