// Update overrides fields' `UPDATE` values.
func (u *CustomFieldScopedUpsertOne) Update(set func(*CustomFieldScopedUpsert)) *CustomFieldScopedUpsertOne {
	u.set = append(u.set, func(r *CustomFieldUpsertOne) {
		r.Update(func(s *CustomFieldUpsert) { set(&CustomFieldScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *CustomFieldScopedUpsertOne) build(ctx context.Context, s *Scoped) (*CustomFieldUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *CustomFieldScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id. An audited upsert must be DO NOTHING:
// an insert is a create, a conflict (sql.ErrNoRows) writes nothing and records nothing.
func (u *CustomFieldScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if u.x.s.auditing() && !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.writeCustomField(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

