// Save verifies the references against the Workspace, then creates the EmailTemplate.
func (x *EmailTemplateScopedCreate) Save(ctx context.Context) (*EmailTemplate, error) {
	var created *EmailTemplate
	err := x.s.writeEmailTemplate(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *EmailTemplateScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// EmailTemplateScopedCreateBulk creates several EmailTemplate entities of one Workspace at once.
type EmailTemplateScopedCreateBulk struct {
	s  *Scoped
	xs []*EmailTemplateScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *EmailTemplateScoped) CreateBulk(xs ...*EmailTemplateScopedCreate) *EmailTemplateScopedCreateBulk {
	return &EmailTemplateScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *EmailTemplateScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("EmailTemplate: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *EmailTemplateScopedCreateBulk) build(ctx context.Context, s *Scoped) (*EmailTemplateCreateBulk, error) {
	builders := make([]*EmailTemplateCreate, len(b.xs))
	ms := make([]*EmailTemplateMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkEmailTemplate(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.EmailTemplate.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the EmailTemplate entities.
func (b *EmailTemplateScopedCreateBulk) Save(ctx context.Context) ([]*EmailTemplate, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*EmailTemplate
	err := b.s.writeEmailTemplate(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *EmailTemplateScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

