// ErasureScoped reaches Erasure entities of one Workspace.
type ErasureScoped struct{ s *Scoped }

// Erasure returns the Erasure entities of the Workspace.
func (s *Scoped) Erasure() *ErasureScoped { return &ErasureScoped{s: s} }

const (
	TypeOf_ErasureScoped             = TypeWrapper
	EntityOf_ErasureScoped           = "Erasure"
	RoleOf_Scoped_Erasure            = RoleNone
	RoleOf_ErasureScoped_Query       = RoleRead
	RoleOf_ErasureScoped_Get         = RoleRead
	RoleOf_ErasureScoped_DeleteOneID = RoleStart
	RoleOf_ErasureScoped_UpdateOneID = RoleStart
	RoleOf_ErasureScoped_Delete      = RoleStart
	RoleOf_ErasureScoped_Create      = RoleStart
	RoleOf_ErasureScoped_CreateBulk  = RoleStart
	RoleOf_ErasureScoped_Update      = RoleStart
)

// inErasure confines predicates of Erasure rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inErasure(ps ...predicate.Erasure) []predicate.Erasure {
	return append([]predicate.Erasure{erasure.WorkspaceID(s.ws)}, ps...)
}

// Query returns a Erasure query already confined to the Workspace.
func (t *ErasureScoped) Query() *ErasureQuery {
	return t.s.c.Erasure.Query().Where(t.s.inErasure()...)
}

// Get returns the Erasure with the id; a row of another Workspace is not found.
func (t *ErasureScoped) Get(ctx context.Context, id int64) (*Erasure, error) {
	return t.Query().Where(erasure.ID(id)).Only(ctx)
}

// writeErasure runs a write of Erasure rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeErasure(ctx context.Context, verb string, where []predicate.Erasure, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkErasure verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkErasure(ctx context.Context, ms ...*ErasureMutation) error {
	return nil
}

// ErasureScopedDeleteOne deletes one Erasure: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type ErasureScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.Erasure
}

// DeleteOneID deletes the Erasure with the id; a row of another Workspace is not found.
func (t *ErasureScoped) DeleteOneID(id int64) *ErasureScopedDeleteOne {
	return &ErasureScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *ErasureScopedDeleteOne) Where(ps ...predicate.Erasure) *ErasureScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_ErasureScopedDeleteOne       = TypeScopedDelete
	EntityOf_ErasureScopedDeleteOne     = "Erasure"
	RoleOf_ErasureScopedDeleteOne_Where = RoleStep
	RoleOf_ErasureScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *ErasureScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inErasure(x.where...)
	return x.s.writeErasure(ctx, "delete", append([]predicate.Erasure{erasure.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.Erasure.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// ErasureScopedDelete deletes the Erasure rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type ErasureScopedDelete struct {
	s     *Scoped
	where []predicate.Erasure
}

// Delete deletes the Erasure entities of the Workspace that match the predicates.
