const RoleOf_ErasureScopedUpdateOne_SetPhoneHashEncrypted = RoleStep

// SetNillablePhoneHashEncrypted sets the "phone_hash_encrypted" field if the given value is not nil.
func (x *ErasureScopedUpdateOne) SetNillablePhoneHashEncrypted(v *string) *ErasureScopedUpdateOne {
	if v != nil {
		x.SetPhoneHashEncrypted(*v)
	}
	return x
}

const RoleOf_ErasureScopedUpdateOne_SetNillablePhoneHashEncrypted = RoleStep

// ClearPhoneHashEncrypted clears the value of the "phone_hash_encrypted" field.
func (x *ErasureScopedUpdateOne) ClearPhoneHashEncrypted() *ErasureScopedUpdateOne {
	x.set = append(x.set, func(b *ErasureUpdateOne) { b.ClearPhoneHashEncrypted() })
	return x
}

const RoleOf_ErasureScopedUpdateOne_ClearPhoneHashEncrypted = RoleStep

// Save verifies the references against the Workspace, then updates the Erasure.
func (x *ErasureScopedUpdateOne) Save(ctx context.Context) (*Erasure, error) {
	return x.save(ctx, "update", skipUnchanged)
}

// build makes the ent update on the client of s and verifies the references it sets.
func (x *ErasureScopedUpdateOne) build(ctx context.Context, s *Scoped) (*ErasureUpdateOne, error) {
	b := s.c.Erasure.UpdateOneID(x.id).Where(s.inErasure(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkErasure(ctx, b.Mutation()))
}

// save is Save under a verb, doing with an unchanged row what unchanged says.
func (x *ErasureScopedUpdateOne) save(ctx context.Context, verb string, unchanged unchangedRows) (*Erasure, error) {
	where := x.s.inErasure(x.where...)
	var updated *Erasure
	err := x.s.writeErasure(ctx, verb, append([]predicate.Erasure{erasure.ID(x.id)}, where...), unchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		updated, err = b.Save(ctx)
		return nil, err
	})
	return written(updated, err)
}

// Exec is like Save, discarding the entity.
func (x *ErasureScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_ErasureScopedUpdateOne       = TypeScopedUpdate
	EntityOf_ErasureScopedUpdateOne     = "Erasure"
	RoleOf_ErasureScopedUpdateOne_Where = RoleStep
	RoleOf_ErasureScopedUpdateOne_Save  = RoleStep
	RoleOf_ErasureScopedUpdateOne_Exec  = RoleStep
)

// ErasureScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type ErasureScopedUpdate struct {
	s     *Scoped
	where []predicate.Erasure
	set   []func(*ErasureUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Erasure entities of the Workspace that match the predicates.
func (t *ErasureScoped) Update() *ErasureScopedUpdate {
	return &ErasureScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *ErasureScopedUpdate) Where(ps ...predicate.Erasure) *ErasureScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *ErasureScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *ErasureScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(erasure.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *ErasureUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

// SetUpdatedAt sets the "updated_at" field.
func (x *ErasureScopedUpdate) SetUpdatedAt(v time.Time) *ErasureScopedUpdate {
	x.set = append(x.set, func(b *ErasureUpdate) { b.SetUpdatedAt(v) })
	return x
}

const RoleOf_ErasureScopedUpdate_SetUpdatedAt = RoleStep

// SetEmailHashEncrypted sets the "email_hash_encrypted" field.
func (x *ErasureScopedUpdate) SetEmailHashEncrypted(v string) *ErasureScopedUpdate {
	x.set = append(x.set, func(b *ErasureUpdate) { b.SetEmailHashEncrypted(v) })
	return x
}

const RoleOf_ErasureScopedUpdate_SetEmailHashEncrypted = RoleStep

// SetNillableEmailHashEncrypted sets the "email_hash_encrypted" field if the given value is not nil.
func (x *ErasureScopedUpdate) SetNillableEmailHashEncrypted(v *string) *ErasureScopedUpdate {
	if v != nil {
		x.SetEmailHashEncrypted(*v)
	}
	return x
}

const RoleOf_ErasureScopedUpdate_SetNillableEmailHashEncrypted = RoleStep

// ClearEmailHashEncrypted clears the value of the "email_hash_encrypted" field.
func (x *ErasureScopedUpdate) ClearEmailHashEncrypted() *ErasureScopedUpdate {
	x.set = append(x.set, func(b *ErasureUpdate) { b.ClearEmailHashEncrypted() })
	return x
}

const RoleOf_ErasureScopedUpdate_ClearEmailHashEncrypted = RoleStep

// SetPhoneHashEncrypted sets the "phone_hash_encrypted" field.
func (x *ErasureScopedUpdate) SetPhoneHashEncrypted(v string) *ErasureScopedUpdate {
	x.set = append(x.set, func(b *ErasureUpdate) { b.SetPhoneHashEncrypted(v) })
	return x
}

const RoleOf_ErasureScopedUpdate_SetPhoneHashEncrypted = RoleStep

// SetNillablePhoneHashEncrypted sets the "phone_hash_encrypted" field if the given value is not nil.
func (x *ErasureScopedUpdate) SetNillablePhoneHashEncrypted(v *string) *ErasureScopedUpdate {
	if v != nil {
		x.SetPhoneHashEncrypted(*v)
	}
	return x
}

const RoleOf_ErasureScopedUpdate_SetNillablePhoneHashEncrypted = RoleStep

// ClearPhoneHashEncrypted clears the value of the "phone_hash_encrypted" field.
func (x *ErasureScopedUpdate) ClearPhoneHashEncrypted() *ErasureScopedUpdate {
	x.set = append(x.set, func(b *ErasureUpdate) { b.ClearPhoneHashEncrypted() })
	return x
}

const RoleOf_ErasureScopedUpdate_ClearPhoneHashEncrypted = RoleStep

// build makes the ent update on the client of s and verifies the references it sets.
func (x *ErasureScopedUpdate) build(ctx context.Context, s *Scoped) (*ErasureUpdate, error) {
	b := s.c.Erasure.Update().Where(s.inErasure(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkErasure(ctx, b.Mutation()))
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *ErasureScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	where := x.s.inErasure(x.where...)
	var n int
	err := x.s.writeErasure(ctx, "update", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		n, err = b.Save(ctx)
		return nil, err
	})
	return written(n, err)
}

// Exec is like Save, discarding the count.
func (x *ErasureScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

