// Save verifies the references against the Workspace, then creates the Event.
func (x *EventScopedCreate) Save(ctx context.Context) (*Event, error) {
	var created *Event
	err := x.s.writeEvent(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *EventScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// EventScopedCreateBulk creates several Event entities of one Workspace at once.
type EventScopedCreateBulk struct {
	s  *Scoped
	xs []*EventScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *EventScoped) CreateBulk(xs ...*EventScopedCreate) *EventScopedCreateBulk {
	return &EventScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *EventScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Event: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *EventScopedCreateBulk) build(ctx context.Context, s *Scoped) (*EventCreateBulk, error) {
	builders := make([]*EventCreate, len(b.xs))
	ms := make([]*EventMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkEvent(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Event.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Event entities.
func (b *EventScopedCreateBulk) Save(ctx context.Context) ([]*Event, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Event
	err := b.s.writeEvent(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *EventScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_EventScopedCreateBulk                   = TypeScopedCreate
	EntityOf_EventScopedCreateBulk                 = "Event"
	RoleOf_EventScopedCreateBulk_Save              = RoleStep
	RoleOf_EventScopedCreateBulk_Exec              = RoleStep
	RoleOf_EventScopedCreateBulk_OnConflictColumns = RoleStart
)

