// Save verifies the references against the Workspace, then creates the Hold.
func (x *HoldScopedCreate) Save(ctx context.Context) (*Hold, error) {
	var created *Hold
	err := x.s.writeHold(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *HoldScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// HoldScopedCreateBulk creates several Hold entities of one Workspace at once.
type HoldScopedCreateBulk struct {
	s  *Scoped
	xs []*HoldScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *HoldScoped) CreateBulk(xs ...*HoldScopedCreate) *HoldScopedCreateBulk {
	return &HoldScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *HoldScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Hold: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *HoldScopedCreateBulk) build(ctx context.Context, s *Scoped) (*HoldCreateBulk, error) {
	builders := make([]*HoldCreate, len(b.xs))
	ms := make([]*HoldMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkHold(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Hold.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Hold entities.
func (b *HoldScopedCreateBulk) Save(ctx context.Context) ([]*Hold, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Hold
	err := b.s.writeHold(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *HoldScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

