// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *HoldScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(hold.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// HoldScopedUpsertOne is the "upsert" of one Hold: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type HoldScopedUpsertOne struct {
	x        *HoldScopedCreate
	conflict []sql.ConflictOption
	set      []func(*HoldUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_HoldScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_HoldScopedUpsertOne               = "Hold"
	RoleOf_HoldScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_HoldScopedUpsertOne_Ignore          = RoleStep
	RoleOf_HoldScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_HoldScopedUpsertOne_Update          = RoleStep
	RoleOf_HoldScopedUpsertOne_Exec            = RoleStep
	RoleOf_HoldScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *HoldScopedCreate) OnConflictColumns(columns ...string) *HoldScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *HoldScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *HoldScopedUpsertOne {
	return &HoldScopedUpsertOne{x: x, conflict: (&HoldScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *HoldScopedUpsertOne) UpdateNewValues() *HoldScopedUpsertOne {
	u.set = append(u.set, func(r *HoldUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *HoldScopedUpsertOne) Ignore() *HoldScopedUpsertOne {
	u.set = append(u.set, func(r *HoldUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *HoldScopedUpsertOne) DoNothing() *HoldScopedUpsertOne {
	u.set = append(u.set, func(r *HoldUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *HoldScopedUpsertOne) Update(set func(*HoldScopedUpsert)) *HoldScopedUpsertOne {
	u.set = append(u.set, func(r *HoldUpsertOne) {
		r.Update(func(s *HoldUpsert) { set(&HoldScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *HoldScopedUpsertOne) build(ctx context.Context, s *Scoped) (*HoldUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *HoldScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id. An audited upsert must be DO NOTHING:
// an insert is a create, a conflict (sql.ErrNoRows) writes nothing and records nothing.
func (u *HoldScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if u.x.s.auditing() && !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.writeHold(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// HoldScopedUpsertBulk is the "upsert" of several Hold entities.
type HoldScopedUpsertBulk struct {
	b       *HoldScopedCreateBulk
	t       *HoldScoped
	columns []string
	set     []func(*HoldUpsertBulk)
}

