// Save verifies the references against the Workspace, then creates the Integration.
func (x *IntegrationScopedCreate) Save(ctx context.Context) (*Integration, error) {
	var created *Integration
	err := x.s.writeIntegration(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *IntegrationScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// IntegrationScopedCreateBulk creates several Integration entities of one Workspace at once.
type IntegrationScopedCreateBulk struct {
	s  *Scoped
	xs []*IntegrationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *IntegrationScoped) CreateBulk(xs ...*IntegrationScopedCreate) *IntegrationScopedCreateBulk {
	return &IntegrationScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *IntegrationScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Integration: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *IntegrationScopedCreateBulk) build(ctx context.Context, s *Scoped) (*IntegrationCreateBulk, error) {
	builders := make([]*IntegrationCreate, len(b.xs))
	ms := make([]*IntegrationMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkIntegration(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Integration.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Integration entities.
func (b *IntegrationScopedCreateBulk) Save(ctx context.Context) ([]*Integration, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Integration
	err := b.s.writeIntegration(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *IntegrationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

