// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *IntegrationScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(integration.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// IntegrationScopedUpsertOne is the "upsert" of one Integration: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type IntegrationScopedUpsertOne struct {
	x        *IntegrationScopedCreate
	conflict []sql.ConflictOption
	set      []func(*IntegrationUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_IntegrationScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_IntegrationScopedUpsertOne               = "Integration"
	RoleOf_IntegrationScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_IntegrationScopedUpsertOne_Ignore          = RoleStep
	RoleOf_IntegrationScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_IntegrationScopedUpsertOne_Update          = RoleStep
	RoleOf_IntegrationScopedUpsertOne_Exec            = RoleStep
	RoleOf_IntegrationScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *IntegrationScopedCreate) OnConflictColumns(columns ...string) *IntegrationScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *IntegrationScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *IntegrationScopedUpsertOne {
	return &IntegrationScopedUpsertOne{x: x, conflict: (&IntegrationScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *IntegrationScopedUpsertOne) UpdateNewValues() *IntegrationScopedUpsertOne {
	u.set = append(u.set, func(r *IntegrationUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *IntegrationScopedUpsertOne) Ignore() *IntegrationScopedUpsertOne {
	u.set = append(u.set, func(r *IntegrationUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *IntegrationScopedUpsertOne) DoNothing() *IntegrationScopedUpsertOne {
	u.set = append(u.set, func(r *IntegrationUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *IntegrationScopedUpsertOne) Update(set func(*IntegrationScopedUpsert)) *IntegrationScopedUpsertOne {
	u.set = append(u.set, func(r *IntegrationUpsertOne) {
		r.Update(func(s *IntegrationUpsert) { set(&IntegrationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *IntegrationScopedUpsertOne) build(ctx context.Context, s *Scoped) (*IntegrationUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *IntegrationScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id. An audited upsert must be DO NOTHING:
// an insert is a create, a conflict (sql.ErrNoRows) writes nothing and records nothing.
func (u *IntegrationScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if u.x.s.auditing() && !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.writeIntegration(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// IntegrationScopedUpsertBulk is the "upsert" of several Integration entities.
type IntegrationScopedUpsertBulk struct {
	b       *IntegrationScopedCreateBulk
	t       *IntegrationScoped
	columns []string
	set     []func(*IntegrationUpsertBulk)
}

const (
	TypeOf_IntegrationScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_IntegrationScopedUpsertBulk               = "Integration"
	RoleOf_IntegrationScopedUpsertBulk_UpdateNewValues = RoleStep
	RoleOf_IntegrationScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_IntegrationScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_IntegrationScopedUpsertBulk_Update          = RoleStep
	RoleOf_IntegrationScopedUpsertBulk_Exec            = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *IntegrationScopedCreateBulk) OnConflictColumns(columns ...string) *IntegrationScopedUpsertBulk {
	return &IntegrationScopedUpsertBulk{b: b, t: &IntegrationScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *IntegrationScopedUpsertBulk) UpdateNewValues() *IntegrationScopedUpsertBulk {
	u.set = append(u.set, func(r *IntegrationUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *IntegrationScopedUpsertBulk) Ignore() *IntegrationScopedUpsertBulk {
	u.set = append(u.set, func(r *IntegrationUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *IntegrationScopedUpsertBulk) DoNothing() *IntegrationScopedUpsertBulk {
	u.set = append(u.set, func(r *IntegrationUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *IntegrationScopedUpsertBulk) Update(set func(*IntegrationScopedUpsert)) *IntegrationScopedUpsertBulk {
	u.set = append(u.set, func(r *IntegrationUpsertBulk) {
		r.Update(func(s *IntegrationUpsert) { set(&IntegrationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert. An audited entity has
// no bulk upsert: it cannot tell an insert from an update.
func (u *IntegrationScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeIntegration(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

