// Save verifies the references against the Workspace, then updates the Integration.
func (x *IntegrationScopedUpdateOne) Save(ctx context.Context) (*Integration, error) {
	return x.save(ctx, "update", skipUnchanged)
}

// build makes the ent update on the client of s and verifies the references it sets.
func (x *IntegrationScopedUpdateOne) build(ctx context.Context, s *Scoped) (*IntegrationUpdateOne, error) {
	b := s.c.Integration.UpdateOneID(x.id).Where(s.inIntegration(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkIntegration(ctx, b.Mutation()))
}

// save is Save under a verb, doing with an unchanged row what unchanged says.
func (x *IntegrationScopedUpdateOne) save(ctx context.Context, verb string, unchanged unchangedRows) (*Integration, error) {
	where := x.s.inIntegration(x.where...)
	var updated *Integration
	err := x.s.writeIntegration(ctx, verb, append([]predicate.Integration{integration.ID(x.id)}, where...), unchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		updated, err = b.Save(ctx)
		return nil, err
	})
	return written(updated, err)
}

// Exec is like Save, discarding the entity.
func (x *IntegrationScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_IntegrationScopedUpdateOne       = TypeScopedUpdate
	EntityOf_IntegrationScopedUpdateOne     = "Integration"
	RoleOf_IntegrationScopedUpdateOne_Where = RoleStep
	RoleOf_IntegrationScopedUpdateOne_Save  = RoleStep
	RoleOf_IntegrationScopedUpdateOne_Exec  = RoleStep
)

// IntegrationScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type IntegrationScopedUpdate struct {
	s     *Scoped
	where []predicate.Integration
	set   []func(*IntegrationUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Integration entities of the Workspace that match the predicates.
func (t *IntegrationScoped) Update() *IntegrationScopedUpdate {
	return &IntegrationScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *IntegrationScopedUpdate) Where(ps ...predicate.Integration) *IntegrationScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *IntegrationScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *IntegrationScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(integration.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *IntegrationUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

