// build makes the ent update on the client of s and verifies the references it sets.
func (x *IntegrationScopedUpdate) build(ctx context.Context, s *Scoped) (*IntegrationUpdate, error) {
	b := s.c.Integration.Update().Where(s.inIntegration(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkIntegration(ctx, b.Mutation()))
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *IntegrationScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	where := x.s.inIntegration(x.where...)
	var n int
	err := x.s.writeIntegration(ctx, "update", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		n, err = b.Save(ctx)
		return nil, err
	})
	return written(n, err)
}

// Exec is like Save, discarding the count.
func (x *IntegrationScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_IntegrationScopedUpdate        = TypeScopedUpdate
	EntityOf_IntegrationScopedUpdate      = "Integration"
	RoleOf_IntegrationScopedUpdate_Where  = RoleStep
	RoleOf_IntegrationScopedUpdate_Modify = RoleStep
	RoleOf_IntegrationScopedUpdate_Save   = RoleStep
	RoleOf_IntegrationScopedUpdate_Exec   = RoleStep
)

// InvitationScoped reaches Invitation entities of one Workspace.
type InvitationScoped struct{ s *Scoped }

// Invitation returns the Invitation entities of the Workspace.
func (s *Scoped) Invitation() *InvitationScoped { return &InvitationScoped{s: s} }

const (
	TypeOf_InvitationScoped             = TypeWrapper
	EntityOf_InvitationScoped           = "Invitation"
	RoleOf_Scoped_Invitation            = RoleNone
	RoleOf_InvitationScoped_Query       = RoleRead
	RoleOf_InvitationScoped_Get         = RoleRead
	RoleOf_InvitationScoped_DeleteOneID = RoleStart
	RoleOf_InvitationScoped_UpdateOneID = RoleStart
	RoleOf_InvitationScoped_Delete      = RoleStart
	RoleOf_InvitationScoped_Create      = RoleStart
	RoleOf_InvitationScoped_CreateBulk  = RoleStart
	RoleOf_InvitationScoped_Update      = RoleStart
)

// inInvitation confines predicates of Invitation rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inInvitation(ps ...predicate.Invitation) []predicate.Invitation {
	return append([]predicate.Invitation{invitation.WorkspaceID(s.ws)}, ps...)
}

// Query returns a Invitation query already confined to the Workspace.
func (t *InvitationScoped) Query() *InvitationQuery {
	return t.s.c.Invitation.Query().Where(t.s.inInvitation()...)
}

// Get returns the Invitation with the id; a row of another Workspace is not found.
func (t *InvitationScoped) Get(ctx context.Context, id int64) (*Invitation, error) {
	return t.Query().Where(invitation.ID(id)).Only(ctx)
}

// writeInvitation runs a write of Invitation rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeInvitation(ctx context.Context, verb string, where []predicate.Invitation, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkInvitation verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkInvitation(ctx context.Context, ms ...*InvitationMutation) error {
	return nil
}

// InvitationScopedDeleteOne deletes one Invitation: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type InvitationScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.Invitation
}

// DeleteOneID deletes the Invitation with the id; a row of another Workspace is not found.
func (t *InvitationScoped) DeleteOneID(id int64) *InvitationScopedDeleteOne {
	return &InvitationScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *InvitationScopedDeleteOne) Where(ps ...predicate.Invitation) *InvitationScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_InvitationScopedDeleteOne       = TypeScopedDelete
	EntityOf_InvitationScopedDeleteOne     = "Invitation"
	RoleOf_InvitationScopedDeleteOne_Where = RoleStep
	RoleOf_InvitationScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *InvitationScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inInvitation(x.where...)
	return x.s.writeInvitation(ctx, "delete", append([]predicate.Invitation{invitation.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.Invitation.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// InvitationScopedDelete deletes the Invitation rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type InvitationScopedDelete struct {
	s     *Scoped
	where []predicate.Invitation
}

// Delete deletes the Invitation entities of the Workspace that match the predicates.
func (t *InvitationScoped) Delete() *InvitationScopedDelete {
	return &InvitationScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *InvitationScopedDelete) Where(ps ...predicate.Invitation) *InvitationScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_InvitationScopedDelete       = TypeScopedDelete
	EntityOf_InvitationScopedDelete     = "Invitation"
	RoleOf_InvitationScopedDelete_Where = RoleStep
	RoleOf_InvitationScopedDelete_Exec  = RoleStep
)

// Exec deletes the rows and returns how many were deleted.
func (x *InvitationScopedDelete) Exec(ctx context.Context) (int, error) {
	where := x.s.inInvitation(x.where...)
	var n int
	err := x.s.writeInvitation(ctx, "delete", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		var err error
		n, err = s.c.Invitation.Delete().Where(where...).Exec(ctx)
		return nil, err
	})
	return written(n, err)
}

// ---------------------------------------------------------------- create

// InvitationScopedCreate creates a Invitation of one Workspace. It has no way to name a Workspace: it
// keeps what its setters set and builds the ent create, in its Workspace, on the client the create
// runs on.
type InvitationScopedCreate struct {
	s   *Scoped
	set []func(*InvitationCreate)
}

// Create starts a Invitation in the Workspace.
func (t *InvitationScoped) Create() *InvitationScopedCreate {
	return &InvitationScopedCreate{s: t.s}
}

// raw makes the ent create on the client of s, in its Workspace, its references not yet verified
// (a bulk create verifies all of its creates' at once).
func (x *InvitationScopedCreate) raw(s *Scoped) *InvitationCreate {
	b := s.c.Invitation.Create().SetWorkspaceID(s.ws)
	for _, set := range x.set {
		set(b)
	}
	return b
}

// build makes the ent create on the client of s and verifies its references.
func (x *InvitationScopedCreate) build(ctx context.Context, s *Scoped) (*InvitationCreate, error) {
	b := x.raw(s)
	return written(b, s.checkInvitation(ctx, b.Mutation()))
}

