// Save verifies the references against the Workspace, then creates the Invitation.
func (x *InvitationScopedCreate) Save(ctx context.Context) (*Invitation, error) {
	var created *Invitation
	err := x.s.writeInvitation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *InvitationScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// InvitationScopedCreateBulk creates several Invitation entities of one Workspace at once.
type InvitationScopedCreateBulk struct {
	s  *Scoped
	xs []*InvitationScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *InvitationScoped) CreateBulk(xs ...*InvitationScopedCreate) *InvitationScopedCreateBulk {
	return &InvitationScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *InvitationScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Invitation: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *InvitationScopedCreateBulk) build(ctx context.Context, s *Scoped) (*InvitationCreateBulk, error) {
	builders := make([]*InvitationCreate, len(b.xs))
	ms := make([]*InvitationMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkInvitation(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Invitation.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Invitation entities.
func (b *InvitationScopedCreateBulk) Save(ctx context.Context) ([]*Invitation, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Invitation
	err := b.s.writeInvitation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *InvitationScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

