// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *InvitationScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(invitation.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// InvitationScopedUpsertOne is the "upsert" of one Invitation: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type InvitationScopedUpsertOne struct {
	x        *InvitationScopedCreate
	conflict []sql.ConflictOption
	set      []func(*InvitationUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_InvitationScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_InvitationScopedUpsertOne               = "Invitation"
	RoleOf_InvitationScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_InvitationScopedUpsertOne_Ignore          = RoleStep
	RoleOf_InvitationScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_InvitationScopedUpsertOne_Update          = RoleStep
	RoleOf_InvitationScopedUpsertOne_Exec            = RoleStep
	RoleOf_InvitationScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *InvitationScopedCreate) OnConflictColumns(columns ...string) *InvitationScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *InvitationScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *InvitationScopedUpsertOne {
	return &InvitationScopedUpsertOne{x: x, conflict: (&InvitationScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *InvitationScopedUpsertOne) UpdateNewValues() *InvitationScopedUpsertOne {
	u.set = append(u.set, func(r *InvitationUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *InvitationScopedUpsertOne) Ignore() *InvitationScopedUpsertOne {
	u.set = append(u.set, func(r *InvitationUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *InvitationScopedUpsertOne) DoNothing() *InvitationScopedUpsertOne {
	u.set = append(u.set, func(r *InvitationUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *InvitationScopedUpsertOne) Update(set func(*InvitationScopedUpsert)) *InvitationScopedUpsertOne {
	u.set = append(u.set, func(r *InvitationUpsertOne) {
		r.Update(func(s *InvitationUpsert) { set(&InvitationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *InvitationScopedUpsertOne) build(ctx context.Context, s *Scoped) (*InvitationUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *InvitationScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id.
func (u *InvitationScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	var id int64
	err := u.x.s.writeInvitation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

