func (u *InvitationScopedUpsertBulk) Update(set func(*InvitationScopedUpsert)) *InvitationScopedUpsertBulk {
	u.set = append(u.set, func(r *InvitationUpsertBulk) {
		r.Update(func(s *InvitationUpsert) { set(&InvitationScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *InvitationScopedUpsertBulk) Exec(ctx context.Context) error {
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeInvitation(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

