// JoinDomainScoped reaches JoinDomain entities of one Workspace.
type JoinDomainScoped struct{ s *Scoped }

// JoinDomain returns the JoinDomain entities of the Workspace.
func (s *Scoped) JoinDomain() *JoinDomainScoped { return &JoinDomainScoped{s: s} }

const (
	TypeOf_JoinDomainScoped             = TypeWrapper
	EntityOf_JoinDomainScoped           = "JoinDomain"
	RoleOf_Scoped_JoinDomain            = RoleNone
	RoleOf_JoinDomainScoped_Query       = RoleRead
	RoleOf_JoinDomainScoped_Get         = RoleRead
	RoleOf_JoinDomainScoped_DeleteOneID = RoleStart
	RoleOf_JoinDomainScoped_UpdateOneID = RoleStart
	RoleOf_JoinDomainScoped_Delete      = RoleStart
	RoleOf_JoinDomainScoped_Create      = RoleStart
	RoleOf_JoinDomainScoped_CreateBulk  = RoleStart
	RoleOf_JoinDomainScoped_Update      = RoleStart
)

// inJoinDomain confines predicates of JoinDomain rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inJoinDomain(ps ...predicate.JoinDomain) []predicate.JoinDomain {
	return append([]predicate.JoinDomain{joindomain.WorkspaceID(s.ws)}, ps...)
}

// Query returns a JoinDomain query already confined to the Workspace.
func (t *JoinDomainScoped) Query() *JoinDomainQuery {
	return t.s.c.JoinDomain.Query().Where(t.s.inJoinDomain()...)
}

// Get returns the JoinDomain with the id; a row of another Workspace is not found.
func (t *JoinDomainScoped) Get(ctx context.Context, id int64) (*JoinDomain, error) {
	return t.Query().Where(joindomain.ID(id)).Only(ctx)
}

// writeJoinDomain runs a write of JoinDomain rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeJoinDomain(ctx context.Context, verb string, where []predicate.JoinDomain, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*JoinDomain
			if where != nil {
				var err error
				if before, err = ts.c.JoinDomain.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*JoinDomain, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.JoinDomain.Query().Where(joindomain.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*JoinDomain, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeJoinDomain(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkJoinDomain verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkJoinDomain(ctx context.Context, ms ...*JoinDomainMutation) error {
	return nil
}

