// Save verifies the references against the Workspace, then creates the JoinDomain.
func (x *JoinDomainScopedCreate) Save(ctx context.Context) (*JoinDomain, error) {
	var created *JoinDomain
	err := x.s.writeJoinDomain(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *JoinDomainScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// JoinDomainScopedCreateBulk creates several JoinDomain entities of one Workspace at once.
type JoinDomainScopedCreateBulk struct {
	s  *Scoped
	xs []*JoinDomainScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *JoinDomainScoped) CreateBulk(xs ...*JoinDomainScopedCreate) *JoinDomainScopedCreateBulk {
	return &JoinDomainScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *JoinDomainScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("JoinDomain: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *JoinDomainScopedCreateBulk) build(ctx context.Context, s *Scoped) (*JoinDomainCreateBulk, error) {
	builders := make([]*JoinDomainCreate, len(b.xs))
	ms := make([]*JoinDomainMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkJoinDomain(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.JoinDomain.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the JoinDomain entities.
func (b *JoinDomainScopedCreateBulk) Save(ctx context.Context) ([]*JoinDomain, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*JoinDomain
	err := b.s.writeJoinDomain(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *JoinDomainScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

