type MembershipScoped struct{ s *Scoped }

// Membership returns the Membership entities of the Workspace.
func (s *Scoped) Membership() *MembershipScoped { return &MembershipScoped{s: s} }

const (
	TypeOf_MembershipScoped             = TypeWrapper
	EntityOf_MembershipScoped           = "Membership"
	RoleOf_Scoped_Membership            = RoleNone
	RoleOf_MembershipScoped_Query       = RoleRead
	RoleOf_MembershipScoped_Get         = RoleRead
	RoleOf_MembershipScoped_DeleteOneID = RoleStart
	RoleOf_MembershipScoped_UpdateOneID = RoleStart
	RoleOf_MembershipScoped_Delete      = RoleStart
	RoleOf_MembershipScoped_Create      = RoleStart
	RoleOf_MembershipScoped_CreateBulk  = RoleStart
	RoleOf_MembershipScoped_Update      = RoleStart
)

// inMembership confines predicates of Membership rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inMembership(ps ...predicate.Membership) []predicate.Membership {
	return append([]predicate.Membership{membership.WorkspaceID(s.ws)}, ps...)
}

// Query returns a Membership query already confined to the Workspace.
func (t *MembershipScoped) Query() *MembershipQuery {
	return t.s.c.Membership.Query().Where(t.s.inMembership()...)
}

// Get returns the Membership with the id; a row of another Workspace is not found.
func (t *MembershipScoped) Get(ctx context.Context, id int64) (*Membership, error) {
	return t.Query().Where(membership.ID(id)).Only(ctx)
}

// writeMembership runs a write of Membership rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeMembership(ctx context.Context, verb string, where []predicate.Membership, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkMembership verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkMembership(ctx context.Context, ms ...*MembershipMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.ConnectionsIDs()...)
		}
		if err := s.verifyApiToken(ctx, ids); err != nil {
			return fmt.Errorf("connections: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.OauthCodesIDs()...)
		}
		if err := s.verifyOAuthCode(ctx, ids); err != nil {
			return fmt.Errorf("oauth_codes: %w", err)
		}
	}
	return nil
}

