// Save verifies the references against the Workspace, then creates the OAuthCode.
func (x *OAuthCodeScopedCreate) Save(ctx context.Context) (*OAuthCode, error) {
	var created *OAuthCode
	err := x.s.writeOAuthCode(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *OAuthCodeScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// OAuthCodeScopedCreateBulk creates several OAuthCode entities of one Workspace at once.
type OAuthCodeScopedCreateBulk struct {
	s  *Scoped
	xs []*OAuthCodeScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *OAuthCodeScoped) CreateBulk(xs ...*OAuthCodeScopedCreate) *OAuthCodeScopedCreateBulk {
	return &OAuthCodeScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *OAuthCodeScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("OAuthCode: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *OAuthCodeScopedCreateBulk) build(ctx context.Context, s *Scoped) (*OAuthCodeCreateBulk, error) {
	builders := make([]*OAuthCodeCreate, len(b.xs))
	ms := make([]*OAuthCodeMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkOAuthCode(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.OAuthCode.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the OAuthCode entities.
func (b *OAuthCodeScopedCreateBulk) Save(ctx context.Context) ([]*OAuthCode, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*OAuthCode
	err := b.s.writeOAuthCode(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *OAuthCodeScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

