// OrderScoped reaches Order entities of one Workspace.
type OrderScoped struct{ s *Scoped }

// Order returns the Order entities of the Workspace.
func (s *Scoped) Order() *OrderScoped { return &OrderScoped{s: s} }

const (
	TypeOf_OrderScoped             = TypeWrapper
	EntityOf_OrderScoped           = "Order"
	RoleOf_Scoped_Order            = RoleNone
	RoleOf_OrderScoped_Query       = RoleRead
	RoleOf_OrderScoped_Get         = RoleRead
	RoleOf_OrderScoped_DeleteOneID = RoleStart
	RoleOf_OrderScoped_UpdateOneID = RoleStart
	RoleOf_OrderScoped_Delete      = RoleStart
	RoleOf_OrderScoped_Create      = RoleStart
	RoleOf_OrderScoped_CreateBulk  = RoleStart
	RoleOf_OrderScoped_Update      = RoleStart
)

// inOrder confines predicates of Order rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inOrder(ps ...predicate.Order) []predicate.Order {
	return append([]predicate.Order{order.WorkspaceID(s.ws)}, ps...)
}

// Query returns a Order query already confined to the Workspace.
func (t *OrderScoped) Query() *OrderQuery {
	return t.s.c.Order.Query().Where(t.s.inOrder()...)
}

// Get returns the Order with the id; a row of another Workspace is not found.
func (t *OrderScoped) Get(ctx context.Context, id int64) (*Order, error) {
	return t.Query().Where(order.ID(id)).Only(ctx)
}

// writeOrder runs a write of Order rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeOrder(ctx context.Context, verb string, where []predicate.Order, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkOrder verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkOrder(ctx context.Context, ms ...*OrderMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.ContactIDs()...)
		}
		if err := s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.BroadcastIDs()...)
		}
		if err := s.verifyBroadcast(ctx, ids); err != nil {
			return fmt.Errorf("broadcast: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.AutomationIDs()...)
		}
		if err := s.verifyAutomation(ctx, ids); err != nil {
			return fmt.Errorf("automation: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.MovementsIDs()...)
		}
		if err := s.verifyOrderMovement(ctx, ids); err != nil {
			return fmt.Errorf("movements: %w", err)
		}
	}
	return nil
}

// OrderScopedDeleteOne deletes one Order: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type OrderScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.Order
}

// DeleteOneID deletes the Order with the id; a row of another Workspace is not found.
func (t *OrderScoped) DeleteOneID(id int64) *OrderScopedDeleteOne {
	return &OrderScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *OrderScopedDeleteOne) Where(ps ...predicate.Order) *OrderScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_OrderScopedDeleteOne       = TypeScopedDelete
	EntityOf_OrderScopedDeleteOne     = "Order"
	RoleOf_OrderScopedDeleteOne_Where = RoleStep
	RoleOf_OrderScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *OrderScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inOrder(x.where...)
	return x.s.writeOrder(ctx, "delete", append([]predicate.Order{order.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.Order.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// OrderScopedDelete deletes the Order rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type OrderScopedDelete struct {
	s     *Scoped
	where []predicate.Order
}

// Delete deletes the Order entities of the Workspace that match the predicates.
func (t *OrderScoped) Delete() *OrderScopedDelete {
	return &OrderScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *OrderScopedDelete) Where(ps ...predicate.Order) *OrderScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_OrderScopedDelete       = TypeScopedDelete
	EntityOf_OrderScopedDelete     = "Order"
	RoleOf_OrderScopedDelete_Where = RoleStep
	RoleOf_OrderScopedDelete_Exec  = RoleStep
)

// Exec deletes the rows and returns how many were deleted.
func (x *OrderScopedDelete) Exec(ctx context.Context) (int, error) {
	where := x.s.inOrder(x.where...)
	var n int
	err := x.s.writeOrder(ctx, "delete", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		var err error
		n, err = s.c.Order.Delete().Where(where...).Exec(ctx)
		return nil, err
	})
	return written(n, err)
}

// ---------------------------------------------------------------- create

// OrderScopedCreate creates a Order of one Workspace. It has no way to name a Workspace: it
// keeps what its setters set and builds the ent create, in its Workspace, on the client the create
// runs on.
type OrderScopedCreate struct {
	s   *Scoped
	set []func(*OrderCreate)
}

// Create starts a Order in the Workspace.
func (t *OrderScoped) Create() *OrderScopedCreate {
	return &OrderScopedCreate{s: t.s}
}

// raw makes the ent create on the client of s, in its Workspace, its references not yet verified
// (a bulk create verifies all of its creates' at once).
func (x *OrderScopedCreate) raw(s *Scoped) *OrderCreate {
	b := s.c.Order.Create().SetWorkspaceID(s.ws)
	for _, set := range x.set {
		set(b)
	}
	return b
}

// build makes the ent create on the client of s and verifies its references.
func (x *OrderScopedCreate) build(ctx context.Context, s *Scoped) (*OrderCreate, error) {
	b := x.raw(s)
	return written(b, s.checkOrder(ctx, b.Mutation()))
}

