// Save verifies the references against the Workspace, then creates the Order.
func (x *OrderScopedCreate) Save(ctx context.Context) (*Order, error) {
	var created *Order
	err := x.s.writeOrder(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *OrderScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// OrderScopedCreateBulk creates several Order entities of one Workspace at once.
type OrderScopedCreateBulk struct {
	s  *Scoped
	xs []*OrderScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *OrderScoped) CreateBulk(xs ...*OrderScopedCreate) *OrderScopedCreateBulk {
	return &OrderScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *OrderScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Order: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *OrderScopedCreateBulk) build(ctx context.Context, s *Scoped) (*OrderCreateBulk, error) {
	builders := make([]*OrderCreate, len(b.xs))
	ms := make([]*OrderMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkOrder(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Order.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Order entities.
func (b *OrderScopedCreateBulk) Save(ctx context.Context) ([]*Order, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Order
	err := b.s.writeOrder(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *OrderScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

