// inOrderMovement confines predicates of OrderMovement rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inOrderMovement(ps ...predicate.OrderMovement) []predicate.OrderMovement {
	return append([]predicate.OrderMovement{ordermovement.WorkspaceID(s.ws)}, ps...)
}

// Query returns a OrderMovement query already confined to the Workspace.
func (t *OrderMovementScoped) Query() *OrderMovementQuery {
	return t.s.c.OrderMovement.Query().Where(t.s.inOrderMovement()...)
}

// Get returns the OrderMovement with the id; a row of another Workspace is not found.
func (t *OrderMovementScoped) Get(ctx context.Context, id int64) (*OrderMovement, error) {
	return t.Query().Where(ordermovement.ID(id)).Only(ctx)
}

// writeOrderMovement runs a write of OrderMovement rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeOrderMovement(ctx context.Context, verb string, where []predicate.OrderMovement, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkOrderMovement verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkOrderMovement(ctx context.Context, ms ...*OrderMovementMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.OrderIDs()...)
		}
		if err := s.verifyOrder(ctx, ids); err != nil {
			return fmt.Errorf("order: %w", err)
		}
	}
	return nil
}

