func (b *OrderMovementScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("OrderMovement: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *OrderMovementScopedCreateBulk) build(ctx context.Context, s *Scoped) (*OrderMovementCreateBulk, error) {
	builders := make([]*OrderMovementCreate, len(b.xs))
	ms := make([]*OrderMovementMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkOrderMovement(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.OrderMovement.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the OrderMovement entities.
func (b *OrderMovementScopedCreateBulk) Save(ctx context.Context) ([]*OrderMovement, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*OrderMovement
	err := b.s.writeOrderMovement(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *OrderMovementScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

