func (t *OutboundMessageScoped) Get(ctx context.Context, id int64) (*OutboundMessage, error) {
	return t.Query().Where(outboundmessage.ID(id)).Only(ctx)
}

// writeOutboundMessage runs a write of OutboundMessage rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeOutboundMessage(ctx context.Context, verb string, where []predicate.OutboundMessage, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkOutboundMessage verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkOutboundMessage(ctx context.Context, ms ...*OutboundMessageMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.TrackedLinksIDs()...)
		}
		if err := s.verifyTrackedLink(ctx, ids); err != nil {
			return fmt.Errorf("tracked_links: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.BroadcastIDs()...)
		}
		if err := s.verifyBroadcast(ctx, ids); err != nil {
			return fmt.Errorf("broadcast: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.AutomationIDs()...)
		}
		if err := s.verifyAutomation(ctx, ids); err != nil {
			return fmt.Errorf("automation: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.IntegrationIDs()...)
		}
		if err := s.verifyIntegration(ctx, ids); err != nil {
			return fmt.Errorf("integration: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.BroadcastRecipientIDs()...)
		}
		if err := s.verifyBroadcastRecipient(ctx, ids); err != nil {
			return fmt.Errorf("broadcast_recipient: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.AutomationRunIDs()...)
		}
		if err := s.verifyAutomationRun(ctx, ids); err != nil {
			return fmt.Errorf("automation_run: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.ContactIDs()...)
		}
		if err := s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.TemplateIDs()...)
		}
		if err := s.verifyEmailTemplate(ctx, ids); err != nil {
			return fmt.Errorf("template: %w", err)
		}
	}
	return nil
}

