// Save verifies the references against the Workspace, then creates the OutboundMessage.
func (x *OutboundMessageScopedCreate) Save(ctx context.Context) (*OutboundMessage, error) {
	var created *OutboundMessage
	err := x.s.writeOutboundMessage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *OutboundMessageScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// OutboundMessageScopedCreateBulk creates several OutboundMessage entities of one Workspace at once.
type OutboundMessageScopedCreateBulk struct {
	s  *Scoped
	xs []*OutboundMessageScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *OutboundMessageScoped) CreateBulk(xs ...*OutboundMessageScopedCreate) *OutboundMessageScopedCreateBulk {
	return &OutboundMessageScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *OutboundMessageScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("OutboundMessage: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *OutboundMessageScopedCreateBulk) build(ctx context.Context, s *Scoped) (*OutboundMessageCreateBulk, error) {
	builders := make([]*OutboundMessageCreate, len(b.xs))
	ms := make([]*OutboundMessageMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkOutboundMessage(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.OutboundMessage.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the OutboundMessage entities.
func (b *OutboundMessageScopedCreateBulk) Save(ctx context.Context) ([]*OutboundMessage, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*OutboundMessage
	err := b.s.writeOutboundMessage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *OutboundMessageScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

