// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *OutboundMessageScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(outboundmessage.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// OutboundMessageScopedUpsertOne is the "upsert" of one OutboundMessage: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type OutboundMessageScopedUpsertOne struct {
	x        *OutboundMessageScopedCreate
	conflict []sql.ConflictOption
	set      []func(*OutboundMessageUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_OutboundMessageScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_OutboundMessageScopedUpsertOne               = "OutboundMessage"
	RoleOf_OutboundMessageScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_OutboundMessageScopedUpsertOne_Ignore          = RoleStep
	RoleOf_OutboundMessageScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_OutboundMessageScopedUpsertOne_Update          = RoleStep
	RoleOf_OutboundMessageScopedUpsertOne_Exec            = RoleStep
	RoleOf_OutboundMessageScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *OutboundMessageScopedCreate) OnConflictColumns(columns ...string) *OutboundMessageScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *OutboundMessageScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *OutboundMessageScopedUpsertOne {
	return &OutboundMessageScopedUpsertOne{x: x, conflict: (&OutboundMessageScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *OutboundMessageScopedUpsertOne) UpdateNewValues() *OutboundMessageScopedUpsertOne {
	u.set = append(u.set, func(r *OutboundMessageUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *OutboundMessageScopedUpsertOne) Ignore() *OutboundMessageScopedUpsertOne {
	u.set = append(u.set, func(r *OutboundMessageUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *OutboundMessageScopedUpsertOne) DoNothing() *OutboundMessageScopedUpsertOne {
	u.set = append(u.set, func(r *OutboundMessageUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *OutboundMessageScopedUpsertOne) Update(set func(*OutboundMessageScopedUpsert)) *OutboundMessageScopedUpsertOne {
	u.set = append(u.set, func(r *OutboundMessageUpsertOne) {
		r.Update(func(s *OutboundMessageUpsert) { set(&OutboundMessageScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *OutboundMessageScopedUpsertOne) build(ctx context.Context, s *Scoped) (*OutboundMessageUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *OutboundMessageScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id.
func (u *OutboundMessageScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	var id int64
	err := u.x.s.writeOutboundMessage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// OutboundMessageScopedUpsertBulk is the "upsert" of several OutboundMessage entities.
type OutboundMessageScopedUpsertBulk struct {
	b       *OutboundMessageScopedCreateBulk
	t       *OutboundMessageScoped
	columns []string
	set     []func(*OutboundMessageUpsertBulk)
}

const (
	TypeOf_OutboundMessageScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_OutboundMessageScopedUpsertBulk               = "OutboundMessage"
	RoleOf_OutboundMessageScopedUpsertBulk_UpdateNewValues = RoleStep
	RoleOf_OutboundMessageScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_OutboundMessageScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_OutboundMessageScopedUpsertBulk_Update          = RoleStep
	RoleOf_OutboundMessageScopedUpsertBulk_Exec            = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *OutboundMessageScopedCreateBulk) OnConflictColumns(columns ...string) *OutboundMessageScopedUpsertBulk {
	return &OutboundMessageScopedUpsertBulk{b: b, t: &OutboundMessageScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *OutboundMessageScopedUpsertBulk) UpdateNewValues() *OutboundMessageScopedUpsertBulk {
	u.set = append(u.set, func(r *OutboundMessageUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *OutboundMessageScopedUpsertBulk) Ignore() *OutboundMessageScopedUpsertBulk {
	u.set = append(u.set, func(r *OutboundMessageUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *OutboundMessageScopedUpsertBulk) DoNothing() *OutboundMessageScopedUpsertBulk {
	u.set = append(u.set, func(r *OutboundMessageUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *OutboundMessageScopedUpsertBulk) Update(set func(*OutboundMessageScopedUpsert)) *OutboundMessageScopedUpsertBulk {
	u.set = append(u.set, func(r *OutboundMessageUpsertBulk) {
		r.Update(func(s *OutboundMessageUpsert) { set(&OutboundMessageScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *OutboundMessageScopedUpsertBulk) Exec(ctx context.Context) error {
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeOutboundMessage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

