// Save verifies the references against the Workspace, then updates the OutboundMessage.
func (x *OutboundMessageScopedUpdateOne) Save(ctx context.Context) (*OutboundMessage, error) {
	return x.save(ctx, "update", skipUnchanged)
}

// build makes the ent update on the client of s and verifies the references it sets.
func (x *OutboundMessageScopedUpdateOne) build(ctx context.Context, s *Scoped) (*OutboundMessageUpdateOne, error) {
	b := s.c.OutboundMessage.UpdateOneID(x.id).Where(s.inOutboundMessage(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkOutboundMessage(ctx, b.Mutation()))
}

// save is Save under a verb, doing with an unchanged row what unchanged says.
func (x *OutboundMessageScopedUpdateOne) save(ctx context.Context, verb string, unchanged unchangedRows) (*OutboundMessage, error) {
	where := x.s.inOutboundMessage(x.where...)
	var updated *OutboundMessage
	err := x.s.writeOutboundMessage(ctx, verb, append([]predicate.OutboundMessage{outboundmessage.ID(x.id)}, where...), unchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		updated, err = b.Save(ctx)
		return nil, err
	})
	return written(updated, err)
}

// Exec is like Save, discarding the entity.
func (x *OutboundMessageScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_OutboundMessageScopedUpdateOne       = TypeScopedUpdate
	EntityOf_OutboundMessageScopedUpdateOne     = "OutboundMessage"
	RoleOf_OutboundMessageScopedUpdateOne_Where = RoleStep
	RoleOf_OutboundMessageScopedUpdateOne_Save  = RoleStep
	RoleOf_OutboundMessageScopedUpdateOne_Exec  = RoleStep
)

// OutboundMessageScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type OutboundMessageScopedUpdate struct {
	s     *Scoped
	where []predicate.OutboundMessage
	set   []func(*OutboundMessageUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the OutboundMessage entities of the Workspace that match the predicates.
func (t *OutboundMessageScoped) Update() *OutboundMessageScopedUpdate {
	return &OutboundMessageScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *OutboundMessageScopedUpdate) Where(ps ...predicate.OutboundMessage) *OutboundMessageScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *OutboundMessageScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *OutboundMessageScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(outboundmessage.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *OutboundMessageUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

