// ProviderLimiterScoped reaches ProviderLimiter entities of one Workspace.
type ProviderLimiterScoped struct{ s *Scoped }

// ProviderLimiter returns the ProviderLimiter entities of the Workspace.
func (s *Scoped) ProviderLimiter() *ProviderLimiterScoped { return &ProviderLimiterScoped{s: s} }

const (
	TypeOf_ProviderLimiterScoped             = TypeWrapper
	EntityOf_ProviderLimiterScoped           = "ProviderLimiter"
	RoleOf_Scoped_ProviderLimiter            = RoleNone
	RoleOf_ProviderLimiterScoped_Query       = RoleRead
	RoleOf_ProviderLimiterScoped_Get         = RoleRead
	RoleOf_ProviderLimiterScoped_DeleteOneID = RoleStart
	RoleOf_ProviderLimiterScoped_UpdateOneID = RoleStart
	RoleOf_ProviderLimiterScoped_Delete      = RoleStart
	RoleOf_ProviderLimiterScoped_Create      = RoleStart
	RoleOf_ProviderLimiterScoped_CreateBulk  = RoleStart
	RoleOf_ProviderLimiterScoped_Update      = RoleStart
)

// inProviderLimiter confines predicates of ProviderLimiter rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inProviderLimiter(ps ...predicate.ProviderLimiter) []predicate.ProviderLimiter {
	return append([]predicate.ProviderLimiter{providerlimiter.WorkspaceID(s.ws)}, ps...)
}

// Query returns a ProviderLimiter query already confined to the Workspace.
func (t *ProviderLimiterScoped) Query() *ProviderLimiterQuery {
	return t.s.c.ProviderLimiter.Query().Where(t.s.inProviderLimiter()...)
}

// Get returns the ProviderLimiter with the id; a row of another Workspace is not found.
func (t *ProviderLimiterScoped) Get(ctx context.Context, id int64) (*ProviderLimiter, error) {
	return t.Query().Where(providerlimiter.ID(id)).Only(ctx)
}

// writeProviderLimiter runs a write of ProviderLimiter rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeProviderLimiter(ctx context.Context, verb string, where []predicate.ProviderLimiter, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkProviderLimiter verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkProviderLimiter(ctx context.Context, ms ...*ProviderLimiterMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.IntegrationIDs()...)
		}
		if err := s.verifyIntegration(ctx, ids); err != nil {
			return fmt.Errorf("integration: %w", err)
		}
	}
	return nil
}

// ProviderLimiterScopedDeleteOne deletes one ProviderLimiter: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type ProviderLimiterScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.ProviderLimiter
}

// DeleteOneID deletes the ProviderLimiter with the id; a row of another Workspace is not found.
func (t *ProviderLimiterScoped) DeleteOneID(id int64) *ProviderLimiterScopedDeleteOne {
	return &ProviderLimiterScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *ProviderLimiterScopedDeleteOne) Where(ps ...predicate.ProviderLimiter) *ProviderLimiterScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_ProviderLimiterScopedDeleteOne       = TypeScopedDelete
	EntityOf_ProviderLimiterScopedDeleteOne     = "ProviderLimiter"
	RoleOf_ProviderLimiterScopedDeleteOne_Where = RoleStep
	RoleOf_ProviderLimiterScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *ProviderLimiterScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inProviderLimiter(x.where...)
	return x.s.writeProviderLimiter(ctx, "delete", append([]predicate.ProviderLimiter{providerlimiter.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.ProviderLimiter.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// ProviderLimiterScopedDelete deletes the ProviderLimiter rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type ProviderLimiterScopedDelete struct {
	s     *Scoped
	where []predicate.ProviderLimiter
}

// Delete deletes the ProviderLimiter entities of the Workspace that match the predicates.
func (t *ProviderLimiterScoped) Delete() *ProviderLimiterScopedDelete {
	return &ProviderLimiterScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *ProviderLimiterScopedDelete) Where(ps ...predicate.ProviderLimiter) *ProviderLimiterScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

