// Save verifies the references against the Workspace, then creates the ProviderLimiter.
func (x *ProviderLimiterScopedCreate) Save(ctx context.Context) (*ProviderLimiter, error) {
	var created *ProviderLimiter
	err := x.s.writeProviderLimiter(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *ProviderLimiterScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// ProviderLimiterScopedCreateBulk creates several ProviderLimiter entities of one Workspace at once.
type ProviderLimiterScopedCreateBulk struct {
	s  *Scoped
	xs []*ProviderLimiterScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *ProviderLimiterScoped) CreateBulk(xs ...*ProviderLimiterScopedCreate) *ProviderLimiterScopedCreateBulk {
	return &ProviderLimiterScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *ProviderLimiterScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("ProviderLimiter: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *ProviderLimiterScopedCreateBulk) build(ctx context.Context, s *Scoped) (*ProviderLimiterCreateBulk, error) {
	builders := make([]*ProviderLimiterCreate, len(b.xs))
	ms := make([]*ProviderLimiterMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkProviderLimiter(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.ProviderLimiter.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the ProviderLimiter entities.
func (b *ProviderLimiterScopedCreateBulk) Save(ctx context.Context) ([]*ProviderLimiter, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*ProviderLimiter
	err := b.s.writeProviderLimiter(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *ProviderLimiterScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

