// RuleScoped reaches Rule entities of one Workspace.
type RuleScoped struct{ s *Scoped }

// Rule returns the Rule entities of the Workspace.
func (s *Scoped) Rule() *RuleScoped { return &RuleScoped{s: s} }

const (
	TypeOf_RuleScoped                    = TypeWrapper
	EntityOf_RuleScoped                  = "Rule"
	RoleOf_Scoped_Rule                   = RoleNone
	RoleOf_RuleScoped_Query              = RoleRead
	RoleOf_RuleScoped_QueryWithDiscarded = RoleRead
	RoleOf_RuleScoped_Discard            = RoleStart
	RoleOf_RuleScoped_Get                = RoleRead
	RoleOf_RuleScoped_PurgeOneID         = RoleStart
	RoleOf_RuleScoped_UpdateOneID        = RoleStart
	RoleOf_RuleScoped_Purge              = RoleStart
	RoleOf_RuleScoped_Create             = RoleStart
	RoleOf_RuleScoped_CreateBulk         = RoleStart
	RoleOf_RuleScoped_Update             = RoleStart
)

// inRule confines predicates of Rule rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inRule(ps ...predicate.Rule) []predicate.Rule {
	return append([]predicate.Rule{rule.WorkspaceID(s.ws)}, ps...)
}

// Query returns a Rule query already confined to the Workspace, hiding discarded rows
// (a list query; QueryWithDiscarded sees them too).
func (t *RuleScoped) Query() *RuleQuery {
	return t.s.c.Rule.Query().Where(t.s.inRule(rule.DiscardedAtIsNil())...)
}

// QueryWithDiscarded returns a Rule query confined to the Workspace that also sees discarded rows.
func (t *RuleScoped) QueryWithDiscarded() *RuleQuery {
	return t.s.c.Rule.Query().Where(t.s.inRule()...)
}

// Get returns the Rule with the id, discarded or not; a row of another Workspace is not found.
func (t *RuleScoped) Get(ctx context.Context, id int64) (*Rule, error) {
	return t.QueryWithDiscarded().Where(rule.ID(id)).Only(ctx)
}

// writeRule runs a write of Rule rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeRule(ctx context.Context, verb string, where []predicate.Rule, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*Rule
			if where != nil {
				var err error
				if before, err = ts.c.Rule.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*Rule, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.Rule.Query().Where(rule.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*Rule, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeRule(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkRule verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkRule(ctx context.Context, ms ...*RuleMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.VersionsIDs()...)
		}
		if err := s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("versions: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.LiveVersionIDs()...)
		}
		if err := s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("live_version: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.DraftVersionIDs()...)
		}
		if err := s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("draft_version: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.FiringsIDs()...)
		}
		if err := s.verifyRuleFiring(ctx, ids); err != nil {
			return fmt.Errorf("firings: %w", err)
		}
	}
	return nil
}

// Discard stamps discarded_at, at `at`, on the kept Rule with the id (ps fence it further); a row of
// another Workspace, an already discarded row or one a predicate excludes is not found. A discarded
// row is never brought back (ADR 0100): the generated client has no Undiscard.
func (t *RuleScoped) Discard(ctx context.Context, id int64, at time.Time, ps ...predicate.Rule) error {
	where := append(t.s.inRule(rule.ID(id), rule.DiscardedAtIsNil()), ps...)
	return t.s.writeRule(ctx, "discard", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		_, err := s.c.Rule.UpdateOneID(id).Where(where...).SetDiscardedAt(at).Save(ctx)
		return nil, err
	})
}

// RuleScopedDeleteOne deletes one Rule: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type RuleScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.Rule
}

// PurgeOneID physically removes the Rule with the id; a row of another Workspace is not found.
func (t *RuleScoped) PurgeOneID(id int64) *RuleScopedDeleteOne {
	return &RuleScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *RuleScopedDeleteOne) Where(ps ...predicate.Rule) *RuleScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_RuleScopedDeleteOne       = TypeScopedDelete
	EntityOf_RuleScopedDeleteOne     = "Rule"
	RoleOf_RuleScopedDeleteOne_Where = RoleStep
	RoleOf_RuleScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *RuleScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inRule(x.where...)
	return x.s.writeRule(ctx, "delete", append([]predicate.Rule{rule.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.Rule.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// RuleScopedDelete deletes the Rule rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type RuleScopedDelete struct {
	s     *Scoped
	where []predicate.Rule
}

// Purge physically removes the Rule entities of the Workspace that match the predicates.
func (t *RuleScoped) Purge() *RuleScopedDelete {
	return &RuleScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *RuleScopedDelete) Where(ps ...predicate.Rule) *RuleScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_RuleScopedDelete       = TypeScopedDelete
	EntityOf_RuleScopedDelete     = "Rule"
	RoleOf_RuleScopedDelete_Where = RoleStep
	RoleOf_RuleScopedDelete_Exec  = RoleStep
)

// Exec deletes the rows and returns how many were deleted.
func (x *RuleScopedDelete) Exec(ctx context.Context) (int, error) {
	where := x.s.inRule(x.where...)
	var n int
	err := x.s.writeRule(ctx, "delete", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		var err error
		n, err = s.c.Rule.Delete().Where(where...).Exec(ctx)
		return nil, err
	})
	return written(n, err)
}

