// Save verifies the references against the Workspace, then creates the Rule.
func (x *RuleScopedCreate) Save(ctx context.Context) (*Rule, error) {
	var created *Rule
	err := x.s.writeRule(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *RuleScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// RuleScopedCreateBulk creates several Rule entities of one Workspace at once.
type RuleScopedCreateBulk struct {
	s  *Scoped
	xs []*RuleScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *RuleScoped) CreateBulk(xs ...*RuleScopedCreate) *RuleScopedCreateBulk {
	return &RuleScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *RuleScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Rule: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *RuleScopedCreateBulk) build(ctx context.Context, s *Scoped) (*RuleCreateBulk, error) {
	builders := make([]*RuleCreate, len(b.xs))
	ms := make([]*RuleMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkRule(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Rule.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Rule entities.
func (b *RuleScopedCreateBulk) Save(ctx context.Context) ([]*Rule, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Rule
	err := b.s.writeRule(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *RuleScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_RuleScopedCreateBulk                   = TypeScopedCreate
	EntityOf_RuleScopedCreateBulk                 = "Rule"
	RoleOf_RuleScopedCreateBulk_Save              = RoleStep
	RoleOf_RuleScopedCreateBulk_Exec              = RoleStep
	RoleOf_RuleScopedCreateBulk_OnConflictColumns = RoleStart
)

