// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *RuleScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(rule.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// RuleScopedUpsertOne is the "upsert" of one Rule: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type RuleScopedUpsertOne struct {
	x        *RuleScopedCreate
	conflict []sql.ConflictOption
	set      []func(*RuleUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_RuleScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_RuleScopedUpsertOne               = "Rule"
	RoleOf_RuleScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_RuleScopedUpsertOne_Ignore          = RoleStep
	RoleOf_RuleScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_RuleScopedUpsertOne_Update          = RoleStep
	RoleOf_RuleScopedUpsertOne_Exec            = RoleStep
	RoleOf_RuleScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *RuleScopedCreate) OnConflictColumns(columns ...string) *RuleScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *RuleScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *RuleScopedUpsertOne {
	return &RuleScopedUpsertOne{x: x, conflict: (&RuleScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *RuleScopedUpsertOne) UpdateNewValues() *RuleScopedUpsertOne {
	u.set = append(u.set, func(r *RuleUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *RuleScopedUpsertOne) Ignore() *RuleScopedUpsertOne {
	u.set = append(u.set, func(r *RuleUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *RuleScopedUpsertOne) DoNothing() *RuleScopedUpsertOne {
	u.set = append(u.set, func(r *RuleUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *RuleScopedUpsertOne) Update(set func(*RuleScopedUpsert)) *RuleScopedUpsertOne {
	u.set = append(u.set, func(r *RuleUpsertOne) {
		r.Update(func(s *RuleUpsert) { set(&RuleScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *RuleScopedUpsertOne) build(ctx context.Context, s *Scoped) (*RuleUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *RuleScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id. An audited upsert must be DO NOTHING:
// an insert is a create, a conflict (sql.ErrNoRows) writes nothing and records nothing.
func (u *RuleScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if u.x.s.auditing() && !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.writeRule(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// RuleScopedUpsertBulk is the "upsert" of several Rule entities.
type RuleScopedUpsertBulk struct {
	b       *RuleScopedCreateBulk
	t       *RuleScoped
	columns []string
	set     []func(*RuleUpsertBulk)
}

const (
	TypeOf_RuleScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_RuleScopedUpsertBulk               = "Rule"
	RoleOf_RuleScopedUpsertBulk_UpdateNewValues = RoleStep
	RoleOf_RuleScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_RuleScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_RuleScopedUpsertBulk_Update          = RoleStep
	RoleOf_RuleScopedUpsertBulk_Exec            = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *RuleScopedCreateBulk) OnConflictColumns(columns ...string) *RuleScopedUpsertBulk {
	return &RuleScopedUpsertBulk{b: b, t: &RuleScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *RuleScopedUpsertBulk) UpdateNewValues() *RuleScopedUpsertBulk {
	u.set = append(u.set, func(r *RuleUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *RuleScopedUpsertBulk) Ignore() *RuleScopedUpsertBulk {
	u.set = append(u.set, func(r *RuleUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *RuleScopedUpsertBulk) DoNothing() *RuleScopedUpsertBulk {
	u.set = append(u.set, func(r *RuleUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *RuleScopedUpsertBulk) Update(set func(*RuleScopedUpsert)) *RuleScopedUpsertBulk {
	u.set = append(u.set, func(r *RuleUpsertBulk) {
		r.Update(func(s *RuleUpsert) { set(&RuleScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert. An audited entity has
// no bulk upsert: it cannot tell an insert from an update.
func (u *RuleScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeRule(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

