// inRuleFiring confines predicates of RuleFiring rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inRuleFiring(ps ...predicate.RuleFiring) []predicate.RuleFiring {
	return append([]predicate.RuleFiring{rulefiring.WorkspaceID(s.ws)}, ps...)
}

// Query returns a RuleFiring query already confined to the Workspace.
func (t *RuleFiringScoped) Query() *RuleFiringQuery {
	return t.s.c.RuleFiring.Query().Where(t.s.inRuleFiring()...)
}

// Get returns the RuleFiring with the id; a row of another Workspace is not found.
func (t *RuleFiringScoped) Get(ctx context.Context, id int64) (*RuleFiring, error) {
	return t.Query().Where(rulefiring.ID(id)).Only(ctx)
}

// writeRuleFiring runs a write of RuleFiring rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeRuleFiring(ctx context.Context, verb string, where []predicate.RuleFiring, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkRuleFiring verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkRuleFiring(ctx context.Context, ms ...*RuleFiringMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.RuleIDs()...)
		}
		if err := s.verifyRule(ctx, ids); err != nil {
			return fmt.Errorf("rule: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.ContactIDs()...)
		}
		if err := s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.VersionIDs()...)
		}
		if err := s.verifyRuleVersion(ctx, ids); err != nil {
			return fmt.Errorf("version: %w", err)
		}
	}
	return nil
}

