// ---------------------------------------------------------------- create bulk

// RuleFiringScopedCreateBulk creates several RuleFiring entities of one Workspace at once.
type RuleFiringScopedCreateBulk struct {
	s  *Scoped
	xs []*RuleFiringScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *RuleFiringScoped) CreateBulk(xs ...*RuleFiringScopedCreate) *RuleFiringScopedCreateBulk {
	return &RuleFiringScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *RuleFiringScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("RuleFiring: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *RuleFiringScopedCreateBulk) build(ctx context.Context, s *Scoped) (*RuleFiringCreateBulk, error) {
	builders := make([]*RuleFiringCreate, len(b.xs))
	ms := make([]*RuleFiringMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkRuleFiring(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.RuleFiring.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the RuleFiring entities.
func (b *RuleFiringScopedCreateBulk) Save(ctx context.Context) ([]*RuleFiring, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*RuleFiring
	err := b.s.writeRuleFiring(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *RuleFiringScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

