// ---------------------------------------------------------------- create bulk

// RuleVersionScopedCreateBulk creates several RuleVersion entities of one Workspace at once.
type RuleVersionScopedCreateBulk struct {
	s  *Scoped
	xs []*RuleVersionScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *RuleVersionScoped) CreateBulk(xs ...*RuleVersionScopedCreate) *RuleVersionScopedCreateBulk {
	return &RuleVersionScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *RuleVersionScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("RuleVersion: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *RuleVersionScopedCreateBulk) build(ctx context.Context, s *Scoped) (*RuleVersionCreateBulk, error) {
	builders := make([]*RuleVersionCreate, len(b.xs))
	ms := make([]*RuleVersionMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkRuleVersion(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.RuleVersion.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the RuleVersion entities.
func (b *RuleVersionScopedCreateBulk) Save(ctx context.Context) ([]*RuleVersion, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*RuleVersion
	err := b.s.writeRuleVersion(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *RuleVersionScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

