func (s *Scoped) Segment() *SegmentScoped { return &SegmentScoped{s: s} }

const (
	TypeOf_SegmentScoped                   = TypeWrapper
	EntityOf_SegmentScoped                 = "Segment"
	RoleOf_Scoped_Segment                  = RoleNone
	RoleOf_SegmentScoped_Query             = RoleRead
	RoleOf_SegmentScoped_QueryWithArchived = RoleRead
	RoleOf_SegmentScoped_QueryArchived     = RoleRead
	RoleOf_SegmentScoped_Archive           = RoleStart
	RoleOf_SegmentScoped_Unarchive         = RoleStart
	RoleOf_SegmentScoped_Get               = RoleRead
	RoleOf_SegmentScoped_PurgeOneID        = RoleStart
	RoleOf_SegmentScoped_UpdateOneID       = RoleStart
	RoleOf_SegmentScoped_Purge             = RoleStart
	RoleOf_SegmentScoped_Create            = RoleStart
	RoleOf_SegmentScoped_CreateBulk        = RoleStart
	RoleOf_SegmentScoped_Update            = RoleStart
)

// inSegment confines predicates of Segment rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inSegment(ps ...predicate.Segment) []predicate.Segment {
	return append([]predicate.Segment{segment.WorkspaceID(s.ws)}, ps...)
}

// Query returns a Segment query already confined to the Workspace, hiding archived rows
// (a list query; QueryWithArchived sees them too).
func (t *SegmentScoped) Query() *SegmentQuery {
	return t.s.c.Segment.Query().Where(t.s.inSegment(segment.ArchivedAtIsNil())...)
}

// QueryWithArchived returns a Segment query confined to the Workspace that also sees archived rows.
func (t *SegmentScoped) QueryWithArchived() *SegmentQuery {
	return t.s.c.Segment.Query().Where(t.s.inSegment()...)
}

// QueryArchived returns a Segment query confined to the Workspace that sees only archived rows
// (the archived view).
func (t *SegmentScoped) QueryArchived() *SegmentQuery {
	return t.QueryWithArchived().Where(segment.ArchivedAtNotNil())
}

// Get returns the Segment with the id, archived or not; a row of another Workspace is not found.
func (t *SegmentScoped) Get(ctx context.Context, id int64) (*Segment, error) {
	return t.QueryWithArchived().Where(segment.ID(id)).Only(ctx)
}

// writeSegment runs a write of Segment rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeSegment(ctx context.Context, verb string, where []predicate.Segment, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*Segment
			if where != nil {
				var err error
				if before, err = ts.c.Segment.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*Segment, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.Segment.Query().Where(segment.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*Segment, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeSegment(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkSegment verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkSegment(ctx context.Context, ms ...*SegmentMutation) error {
	return nil
}

// Archive stamps archived_at, at `at`, on the kept Segment with the id (ps fence it further); a row of
// another Workspace, an already archived row or one a predicate excludes is not found.
func (t *SegmentScoped) Archive(ctx context.Context, id int64, at time.Time, ps ...predicate.Segment) error {
	where := append(t.s.inSegment(segment.ID(id), segment.ArchivedAtIsNil()), ps...)
	return t.setArchived(ctx, id, where, "archive", func(u *SegmentUpdateOne) { u.SetArchivedAt(at) })
}

// Unarchive clears archived_at on the Segment with the id. Unarchiving a kept row changes
// nothing; only a row that does not exist in the Workspace is not found.
func (t *SegmentScoped) Unarchive(ctx context.Context, id int64) error {
	where := t.s.inSegment(segment.ID(id), segment.ArchivedAtNotNil())
	err := t.setArchived(ctx, id, where, "unarchive", func(u *SegmentUpdateOne) { u.ClearArchivedAt() })
	if !IsNotFound(err) {
		return err
	}
	_, err = t.Get(ctx, id)
	return err
}

func (t *SegmentScoped) setArchived(ctx context.Context, id int64, where []predicate.Segment, verb string, set func(*SegmentUpdateOne)) error {
	return t.s.writeSegment(ctx, verb, where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		u := s.c.Segment.UpdateOneID(id).Where(where...)
		set(u)
		_, err := u.Save(ctx)
		return nil, err
	})
}

