// SegmentScopedCreateBulk creates several Segment entities of one Workspace at once.
type SegmentScopedCreateBulk struct {
	s  *Scoped
	xs []*SegmentScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *SegmentScoped) CreateBulk(xs ...*SegmentScopedCreate) *SegmentScopedCreateBulk {
	return &SegmentScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *SegmentScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Segment: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *SegmentScopedCreateBulk) build(ctx context.Context, s *Scoped) (*SegmentCreateBulk, error) {
	builders := make([]*SegmentCreate, len(b.xs))
	ms := make([]*SegmentMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkSegment(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Segment.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Segment entities.
func (b *SegmentScopedCreateBulk) Save(ctx context.Context) ([]*Segment, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Segment
	err := b.s.writeSegment(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *SegmentScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

