// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *SegmentScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(segment.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// SegmentScopedUpsertOne is the "upsert" of one Segment: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type SegmentScopedUpsertOne struct {
	x        *SegmentScopedCreate
	conflict []sql.ConflictOption
	set      []func(*SegmentUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_SegmentScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_SegmentScopedUpsertOne               = "Segment"
	RoleOf_SegmentScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_SegmentScopedUpsertOne_Ignore          = RoleStep
	RoleOf_SegmentScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_SegmentScopedUpsertOne_Update          = RoleStep
	RoleOf_SegmentScopedUpsertOne_Exec            = RoleStep
	RoleOf_SegmentScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *SegmentScopedCreate) OnConflictColumns(columns ...string) *SegmentScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *SegmentScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *SegmentScopedUpsertOne {
	return &SegmentScopedUpsertOne{x: x, conflict: (&SegmentScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SegmentScopedUpsertOne) UpdateNewValues() *SegmentScopedUpsertOne {
	u.set = append(u.set, func(r *SegmentUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SegmentScopedUpsertOne) Ignore() *SegmentScopedUpsertOne {
	u.set = append(u.set, func(r *SegmentUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SegmentScopedUpsertOne) DoNothing() *SegmentScopedUpsertOne {
	u.set = append(u.set, func(r *SegmentUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SegmentScopedUpsertOne) Update(set func(*SegmentScopedUpsert)) *SegmentScopedUpsertOne {
	u.set = append(u.set, func(r *SegmentUpsertOne) {
		r.Update(func(s *SegmentUpsert) { set(&SegmentScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *SegmentScopedUpsertOne) build(ctx context.Context, s *Scoped) (*SegmentUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *SegmentScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id. An audited upsert must be DO NOTHING:
// an insert is a create, a conflict (sql.ErrNoRows) writes nothing and records nothing.
func (u *SegmentScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	if u.x.s.auditing() && !u.doNothing {
		return 0, ErrAuditUpsert
	}
	var id int64
	err := u.x.s.writeSegment(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// SegmentScopedUpsertBulk is the "upsert" of several Segment entities.
type SegmentScopedUpsertBulk struct {
	b       *SegmentScopedCreateBulk
	t       *SegmentScoped
	columns []string
	set     []func(*SegmentUpsertBulk)
}

const (
	TypeOf_SegmentScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_SegmentScopedUpsertBulk               = "Segment"
	RoleOf_SegmentScopedUpsertBulk_UpdateNewValues = RoleStep
	RoleOf_SegmentScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_SegmentScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_SegmentScopedUpsertBulk_Update          = RoleStep
	RoleOf_SegmentScopedUpsertBulk_Exec            = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *SegmentScopedCreateBulk) OnConflictColumns(columns ...string) *SegmentScopedUpsertBulk {
	return &SegmentScopedUpsertBulk{b: b, t: &SegmentScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *SegmentScopedUpsertBulk) UpdateNewValues() *SegmentScopedUpsertBulk {
	u.set = append(u.set, func(r *SegmentUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *SegmentScopedUpsertBulk) Ignore() *SegmentScopedUpsertBulk {
	u.set = append(u.set, func(r *SegmentUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *SegmentScopedUpsertBulk) DoNothing() *SegmentScopedUpsertBulk {
	u.set = append(u.set, func(r *SegmentUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *SegmentScopedUpsertBulk) Update(set func(*SegmentScopedUpsert)) *SegmentScopedUpsertBulk {
	u.set = append(u.set, func(r *SegmentUpsertBulk) {
		r.Update(func(s *SegmentUpsert) { set(&SegmentScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert. An audited entity has
// no bulk upsert: it cannot tell an insert from an update.
func (u *SegmentScopedUpsertBulk) Exec(ctx context.Context) error {
	if u.b.s.auditing() {
		return ErrAuditUpsert
	}
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeSegment(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

