func (x *SendCapLimiterScopedUpdate) SetUpdatedAt(v time.Time) *SendCapLimiterScopedUpdate {
	x.set = append(x.set, func(b *SendCapLimiterUpdate) { b.SetUpdatedAt(v) })
	return x
}

