// inSendingDomain confines predicates of SendingDomain rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inSendingDomain(ps ...predicate.SendingDomain) []predicate.SendingDomain {
	return append([]predicate.SendingDomain{sendingdomain.WorkspaceID(s.ws)}, ps...)
}

// Query returns a SendingDomain query already confined to the Workspace, hiding discarded rows
// (a list query; QueryWithDiscarded sees them too).
func (t *SendingDomainScoped) Query() *SendingDomainQuery {
	return t.s.c.SendingDomain.Query().Where(t.s.inSendingDomain(sendingdomain.DiscardedAtIsNil())...)
}

// QueryWithDiscarded returns a SendingDomain query confined to the Workspace that also sees discarded rows.
func (t *SendingDomainScoped) QueryWithDiscarded() *SendingDomainQuery {
	return t.s.c.SendingDomain.Query().Where(t.s.inSendingDomain()...)
}

// Get returns the SendingDomain with the id, discarded or not; a row of another Workspace is not found.
func (t *SendingDomainScoped) Get(ctx context.Context, id int64) (*SendingDomain, error) {
	return t.QueryWithDiscarded().Where(sendingdomain.ID(id)).Only(ctx)
}

// writeSendingDomain runs a write of SendingDomain rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeSendingDomain(ctx context.Context, verb string, where []predicate.SendingDomain, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*SendingDomain
			if where != nil {
				var err error
				if before, err = ts.c.SendingDomain.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*SendingDomain, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.SendingDomain.Query().Where(sendingdomain.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*SendingDomain, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeSendingDomain(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkSendingDomain verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkSendingDomain(ctx context.Context, ms ...*SendingDomainMutation) error {
	return nil
}

// Discard stamps discarded_at, at `at`, on the kept SendingDomain with the id (ps fence it further); a row of
// another Workspace, an already discarded row or one a predicate excludes is not found. A discarded
// row is never brought back (ADR 0100): the generated client has no Undiscard.
func (t *SendingDomainScoped) Discard(ctx context.Context, id int64, at time.Time, ps ...predicate.SendingDomain) error {
	where := append(t.s.inSendingDomain(sendingdomain.ID(id), sendingdomain.DiscardedAtIsNil()), ps...)
	return t.s.writeSendingDomain(ctx, "discard", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		_, err := s.c.SendingDomain.UpdateOneID(id).Where(where...).SetDiscardedAt(at).Save(ctx)
		return nil, err
	})
}

