// Save verifies the references against the Workspace, then creates the SendingDomain.
func (x *SendingDomainScopedCreate) Save(ctx context.Context) (*SendingDomain, error) {
	var created *SendingDomain
	err := x.s.writeSendingDomain(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *SendingDomainScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// SendingDomainScopedCreateBulk creates several SendingDomain entities of one Workspace at once.
type SendingDomainScopedCreateBulk struct {
	s  *Scoped
	xs []*SendingDomainScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *SendingDomainScoped) CreateBulk(xs ...*SendingDomainScopedCreate) *SendingDomainScopedCreateBulk {
	return &SendingDomainScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *SendingDomainScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("SendingDomain: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *SendingDomainScopedCreateBulk) build(ctx context.Context, s *Scoped) (*SendingDomainCreateBulk, error) {
	builders := make([]*SendingDomainCreate, len(b.xs))
	ms := make([]*SendingDomainMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkSendingDomain(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.SendingDomain.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the SendingDomain entities.
func (b *SendingDomainScopedCreateBulk) Save(ctx context.Context) ([]*SendingDomain, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*SendingDomain
	err := b.s.writeSendingDomain(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *SendingDomainScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

