// StartTokenScoped reaches StartToken entities of one Workspace.
type StartTokenScoped struct{ s *Scoped }

// StartToken returns the StartToken entities of the Workspace.
func (s *Scoped) StartToken() *StartTokenScoped { return &StartTokenScoped{s: s} }

const (
	TypeOf_StartTokenScoped             = TypeWrapper
	EntityOf_StartTokenScoped           = "StartToken"
	RoleOf_Scoped_StartToken            = RoleNone
	RoleOf_StartTokenScoped_Query       = RoleRead
	RoleOf_StartTokenScoped_Get         = RoleRead
	RoleOf_StartTokenScoped_DeleteOneID = RoleStart
	RoleOf_StartTokenScoped_UpdateOneID = RoleStart
	RoleOf_StartTokenScoped_Delete      = RoleStart
	RoleOf_StartTokenScoped_Create      = RoleStart
	RoleOf_StartTokenScoped_CreateBulk  = RoleStart
	RoleOf_StartTokenScoped_Update      = RoleStart
)

// inStartToken confines predicates of StartToken rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inStartToken(ps ...predicate.StartToken) []predicate.StartToken {
	return append([]predicate.StartToken{starttoken.WorkspaceID(s.ws)}, ps...)
}

// Query returns a StartToken query already confined to the Workspace.
func (t *StartTokenScoped) Query() *StartTokenQuery {
	return t.s.c.StartToken.Query().Where(t.s.inStartToken()...)
}

// Get returns the StartToken with the id; a row of another Workspace is not found.
func (t *StartTokenScoped) Get(ctx context.Context, id int64) (*StartToken, error) {
	return t.Query().Where(starttoken.ID(id)).Only(ctx)
}

// writeStartToken runs a write of StartToken rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeStartToken(ctx context.Context, verb string, where []predicate.StartToken, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkStartToken verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkStartToken(ctx context.Context, ms ...*StartTokenMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.IntegrationIDs()...)
		}
		if err := s.verifyIntegration(ctx, ids); err != nil {
			return fmt.Errorf("integration: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.ContactIDs()...)
		}
		if err := s.verifyContact(ctx, ids); err != nil {
			return fmt.Errorf("contact: %w", err)
		}
	}
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.VisitorIDs()...)
		}
		if err := s.verifyVisitor(ctx, ids); err != nil {
			return fmt.Errorf("visitor: %w", err)
		}
	}
	return nil
}

