// Save verifies the references against the Workspace, then creates the StartToken.
func (x *StartTokenScopedCreate) Save(ctx context.Context) (*StartToken, error) {
	var created *StartToken
	err := x.s.writeStartToken(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *StartTokenScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// StartTokenScopedCreateBulk creates several StartToken entities of one Workspace at once.
type StartTokenScopedCreateBulk struct {
	s  *Scoped
	xs []*StartTokenScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *StartTokenScoped) CreateBulk(xs ...*StartTokenScopedCreate) *StartTokenScopedCreateBulk {
	return &StartTokenScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *StartTokenScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("StartToken: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *StartTokenScopedCreateBulk) build(ctx context.Context, s *Scoped) (*StartTokenCreateBulk, error) {
	builders := make([]*StartTokenCreate, len(b.xs))
	ms := make([]*StartTokenMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkStartToken(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.StartToken.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the StartToken entities.
func (b *StartTokenScopedCreateBulk) Save(ctx context.Context) ([]*StartToken, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*StartToken
	err := b.s.writeStartToken(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *StartTokenScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

