// StartTokenScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type StartTokenScopedUpdate struct {
	s     *Scoped
	where []predicate.StartToken
	set   []func(*StartTokenUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the StartToken entities of the Workspace that match the predicates.
func (t *StartTokenScoped) Update() *StartTokenScopedUpdate {
	return &StartTokenScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *StartTokenScopedUpdate) Where(ps ...predicate.StartToken) *StartTokenScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *StartTokenScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *StartTokenScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(starttoken.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *StartTokenUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

// SetUpdatedAt sets the "updated_at" field.
func (x *StartTokenScopedUpdate) SetUpdatedAt(v time.Time) *StartTokenScopedUpdate {
	x.set = append(x.set, func(b *StartTokenUpdate) { b.SetUpdatedAt(v) })
	return x
}

const RoleOf_StartTokenScopedUpdate_SetUpdatedAt = RoleStep

// SetUsedAt sets the "used_at" field.
func (x *StartTokenScopedUpdate) SetUsedAt(v time.Time) *StartTokenScopedUpdate {
	x.set = append(x.set, func(b *StartTokenUpdate) { b.SetUsedAt(v) })
	return x
}

const RoleOf_StartTokenScopedUpdate_SetUsedAt = RoleStep

const SetsState_StartTokenScopedUpdate_SetUsedAt = "UsedAt"

// SetNillableUsedAt sets the "used_at" field if the given value is not nil.
func (x *StartTokenScopedUpdate) SetNillableUsedAt(v *time.Time) *StartTokenScopedUpdate {
	if v != nil {
		x.SetUsedAt(*v)
	}
	return x
}

const RoleOf_StartTokenScopedUpdate_SetNillableUsedAt = RoleStep

const SetsState_StartTokenScopedUpdate_SetNillableUsedAt = "UsedAt"

// ClearUsedAt clears the value of the "used_at" field.
func (x *StartTokenScopedUpdate) ClearUsedAt() *StartTokenScopedUpdate {
	x.set = append(x.set, func(b *StartTokenUpdate) { b.ClearUsedAt() })
	return x
}

const RoleOf_StartTokenScopedUpdate_ClearUsedAt = RoleStep

const ClearsState_StartTokenScopedUpdate_ClearUsedAt = "UsedAt"

// build makes the ent update on the client of s and verifies the references it sets.
func (x *StartTokenScopedUpdate) build(ctx context.Context, s *Scoped) (*StartTokenUpdate, error) {
	b := s.c.StartToken.Update().Where(s.inStartToken(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkStartToken(ctx, b.Mutation()))
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *StartTokenScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	where := x.s.inStartToken(x.where...)
	var n int
	err := x.s.writeStartToken(ctx, "update", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		n, err = b.Save(ctx)
		return nil, err
	})
	return written(n, err)
}

// Exec is like Save, discarding the count.
func (x *StartTokenScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

