// Save verifies the references against the Workspace, then creates the Suppression.
func (x *SuppressionScopedCreate) Save(ctx context.Context) (*Suppression, error) {
	var created *Suppression
	err := x.s.writeSuppression(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *SuppressionScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// SuppressionScopedCreateBulk creates several Suppression entities of one Workspace at once.
type SuppressionScopedCreateBulk struct {
	s  *Scoped
	xs []*SuppressionScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *SuppressionScoped) CreateBulk(xs ...*SuppressionScopedCreate) *SuppressionScopedCreateBulk {
	return &SuppressionScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *SuppressionScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Suppression: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *SuppressionScopedCreateBulk) build(ctx context.Context, s *Scoped) (*SuppressionCreateBulk, error) {
	builders := make([]*SuppressionCreate, len(b.xs))
	ms := make([]*SuppressionMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkSuppression(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Suppression.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Suppression entities.
func (b *SuppressionScopedCreateBulk) Save(ctx context.Context) ([]*Suppression, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Suppression
	err := b.s.writeSuppression(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *SuppressionScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

