	RoleOf_TagScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_TagScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_TagScopedUpsertBulk_Update          = RoleStep
	RoleOf_TagScopedUpsertBulk_Exec            = RoleStep
