// TagScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type TagScopedUpdate struct {
	s     *Scoped
	where []predicate.Tag
	set   []func(*TagUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the Tag entities of the Workspace that match the predicates.
func (t *TagScoped) Update() *TagScopedUpdate {
	return &TagScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *TagScopedUpdate) Where(ps ...predicate.Tag) *TagScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *TagScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *TagScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(tag.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *TagUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

// SetUpdatedAt sets the "updated_at" field.
func (x *TagScopedUpdate) SetUpdatedAt(v time.Time) *TagScopedUpdate {
	x.set = append(x.set, func(b *TagUpdate) { b.SetUpdatedAt(v) })
	return x
}

const RoleOf_TagScopedUpdate_SetUpdatedAt = RoleStep

// SetName sets the "name" field.
func (x *TagScopedUpdate) SetName(v string) *TagScopedUpdate {
	x.set = append(x.set, func(b *TagUpdate) { b.SetName(v) })
	return x
}

const RoleOf_TagScopedUpdate_SetName = RoleStep

// SetNillableName sets the "name" field if the given value is not nil.
func (x *TagScopedUpdate) SetNillableName(v *string) *TagScopedUpdate {
	if v != nil {
		x.SetName(*v)
	}
	return x
}

const RoleOf_TagScopedUpdate_SetNillableName = RoleStep

// build makes the ent update on the client of s and verifies the references it sets.
func (x *TagScopedUpdate) build(ctx context.Context, s *Scoped) (*TagUpdate, error) {
	b := s.c.Tag.Update().Where(s.inTag(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkTag(ctx, b.Mutation()))
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *TagScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	where := x.s.inTag(x.where...)
	var n int
	err := x.s.writeTag(ctx, "update", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		n, err = b.Save(ctx)
		return nil, err
	})
	return written(n, err)
}

// Exec is like Save, discarding the count.
func (x *TagScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_TagScopedUpdate        = TypeScopedUpdate
	EntityOf_TagScopedUpdate      = "Tag"
	RoleOf_TagScopedUpdate_Where  = RoleStep
	RoleOf_TagScopedUpdate_Modify = RoleStep
	RoleOf_TagScopedUpdate_Save   = RoleStep
	RoleOf_TagScopedUpdate_Exec   = RoleStep
)

// TrackedLinkScoped reaches TrackedLink entities of one Workspace.
type TrackedLinkScoped struct{ s *Scoped }

// TrackedLink returns the TrackedLink entities of the Workspace.
func (s *Scoped) TrackedLink() *TrackedLinkScoped { return &TrackedLinkScoped{s: s} }

const (
	TypeOf_TrackedLinkScoped             = TypeWrapper
	EntityOf_TrackedLinkScoped           = "TrackedLink"
	RoleOf_Scoped_TrackedLink            = RoleNone
	RoleOf_TrackedLinkScoped_Query       = RoleRead
	RoleOf_TrackedLinkScoped_Get         = RoleRead
	RoleOf_TrackedLinkScoped_DeleteOneID = RoleStart
	RoleOf_TrackedLinkScoped_UpdateOneID = RoleStart
	RoleOf_TrackedLinkScoped_Delete      = RoleStart
	RoleOf_TrackedLinkScoped_Create      = RoleStart
	RoleOf_TrackedLinkScoped_CreateBulk  = RoleStart
	RoleOf_TrackedLinkScoped_Update      = RoleStart
)

// inTrackedLink confines predicates of TrackedLink rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inTrackedLink(ps ...predicate.TrackedLink) []predicate.TrackedLink {
	return append([]predicate.TrackedLink{trackedlink.WorkspaceID(s.ws)}, ps...)
}

// Query returns a TrackedLink query already confined to the Workspace.
func (t *TrackedLinkScoped) Query() *TrackedLinkQuery {
	return t.s.c.TrackedLink.Query().Where(t.s.inTrackedLink()...)
}

// Get returns the TrackedLink with the id; a row of another Workspace is not found.
func (t *TrackedLinkScoped) Get(ctx context.Context, id int64) (*TrackedLink, error) {
	return t.Query().Where(trackedlink.ID(id)).Only(ctx)
}

// writeTrackedLink runs a write of TrackedLink rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. The
// entity is not audited, so run gets the scope itself.
func (s *Scoped) writeTrackedLink(ctx context.Context, verb string, where []predicate.TrackedLink, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	_, _, _ = verb, where, unchanged
	_, err := run(s)
	return err
}

// checkTrackedLink verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkTrackedLink(ctx context.Context, ms ...*TrackedLinkMutation) error {
	{
		var ids []int64
		for _, m := range ms {
			ids = append(ids, m.OutboundMessageIDs()...)
		}
		if err := s.verifyOutboundMessage(ctx, ids); err != nil {
			return fmt.Errorf("outbound_message: %w", err)
		}
	}
	return nil
}

// TrackedLinkScopedDeleteOne deletes one TrackedLink: it keeps the row's id and its fences, and builds the
// ent delete on the client the delete runs on.
type TrackedLinkScopedDeleteOne struct {
	s     *Scoped
	id    int64
	where []predicate.TrackedLink
}

// DeleteOneID deletes the TrackedLink with the id; a row of another Workspace is not found.
func (t *TrackedLinkScoped) DeleteOneID(id int64) *TrackedLinkScopedDeleteOne {
	return &TrackedLinkScopedDeleteOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *TrackedLinkScopedDeleteOne) Where(ps ...predicate.TrackedLink) *TrackedLinkScopedDeleteOne {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_TrackedLinkScopedDeleteOne       = TypeScopedDelete
	EntityOf_TrackedLinkScopedDeleteOne     = "TrackedLink"
	RoleOf_TrackedLinkScopedDeleteOne_Where = RoleStep
	RoleOf_TrackedLinkScopedDeleteOne_Exec  = RoleStep
)

// Exec deletes the row; a missing row is a NotFoundError.
func (x *TrackedLinkScopedDeleteOne) Exec(ctx context.Context) error {
	where := x.s.inTrackedLink(x.where...)
	return x.s.writeTrackedLink(ctx, "delete", append([]predicate.TrackedLink{trackedlink.ID(x.id)}, where...), skipUnchanged, func(s *Scoped) ([]int64, error) {
		return nil, s.c.TrackedLink.DeleteOneID(x.id).Where(where...).Exec(ctx)
	})
}

// TrackedLinkScopedDelete deletes the TrackedLink rows of one Workspace that match its predicates, which it
// keeps until the delete is built on the client it runs on.
type TrackedLinkScopedDelete struct {
	s     *Scoped
	where []predicate.TrackedLink
}

// Delete deletes the TrackedLink entities of the Workspace that match the predicates.
func (t *TrackedLinkScoped) Delete() *TrackedLinkScopedDelete {
	return &TrackedLinkScopedDelete{s: t.s}
}

// Where appends predicates the rows must match.
func (x *TrackedLinkScopedDelete) Where(ps ...predicate.TrackedLink) *TrackedLinkScopedDelete {
	x.where = append(x.where, ps...)
	return x
}

const (
	TypeOf_TrackedLinkScopedDelete       = TypeScopedDelete
	EntityOf_TrackedLinkScopedDelete     = "TrackedLink"
	RoleOf_TrackedLinkScopedDelete_Where = RoleStep
	RoleOf_TrackedLinkScopedDelete_Exec  = RoleStep
)

// Exec deletes the rows and returns how many were deleted.
func (x *TrackedLinkScopedDelete) Exec(ctx context.Context) (int, error) {
	where := x.s.inTrackedLink(x.where...)
	var n int
	err := x.s.writeTrackedLink(ctx, "delete", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		var err error
		n, err = s.c.TrackedLink.Delete().Where(where...).Exec(ctx)
		return nil, err
	})
	return written(n, err)
}

// ---------------------------------------------------------------- create

// TrackedLinkScopedCreate creates a TrackedLink of one Workspace. It has no way to name a Workspace: it
// keeps what its setters set and builds the ent create, in its Workspace, on the client the create
// runs on.
type TrackedLinkScopedCreate struct {
	s   *Scoped
	set []func(*TrackedLinkCreate)
}

// Create starts a TrackedLink in the Workspace.
func (t *TrackedLinkScoped) Create() *TrackedLinkScopedCreate {
	return &TrackedLinkScopedCreate{s: t.s}
}

// raw makes the ent create on the client of s, in its Workspace, its references not yet verified
// (a bulk create verifies all of its creates' at once).
func (x *TrackedLinkScopedCreate) raw(s *Scoped) *TrackedLinkCreate {
	b := s.c.TrackedLink.Create().SetWorkspaceID(s.ws)
	for _, set := range x.set {
		set(b)
	}
	return b
}

// build makes the ent create on the client of s and verifies its references.
func (x *TrackedLinkScopedCreate) build(ctx context.Context, s *Scoped) (*TrackedLinkCreate, error) {
	b := x.raw(s)
	return written(b, s.checkTrackedLink(ctx, b.Mutation()))
}

