const (
	TypeOf_TrackedLinkScopedCreate                        = TypeScopedCreate
	EntityOf_TrackedLinkScopedCreate                      = "TrackedLink"
	RoleOf_TrackedLinkScopedCreate_Save                   = RoleStep
	RoleOf_TrackedLinkScopedCreate_Exec                   = RoleStep
	RoleOf_TrackedLinkScopedCreate_OnConflictColumns      = RoleStart
	RoleOf_TrackedLinkScopedCreate_OnConflictColumnsWhere = RoleStart
)

// Save verifies the references against the Workspace, then creates the TrackedLink.
func (x *TrackedLinkScopedCreate) Save(ctx context.Context) (*TrackedLink, error) {
	var created *TrackedLink
	err := x.s.writeTrackedLink(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *TrackedLinkScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// TrackedLinkScopedCreateBulk creates several TrackedLink entities of one Workspace at once.
type TrackedLinkScopedCreateBulk struct {
	s  *Scoped
	xs []*TrackedLinkScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *TrackedLinkScoped) CreateBulk(xs ...*TrackedLinkScopedCreate) *TrackedLinkScopedCreateBulk {
	return &TrackedLinkScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *TrackedLinkScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("TrackedLink: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *TrackedLinkScopedCreateBulk) build(ctx context.Context, s *Scoped) (*TrackedLinkCreateBulk, error) {
	builders := make([]*TrackedLinkCreate, len(b.xs))
	ms := make([]*TrackedLinkMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkTrackedLink(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.TrackedLink.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the TrackedLink entities.
func (b *TrackedLinkScopedCreateBulk) Save(ctx context.Context) ([]*TrackedLink, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*TrackedLink
	err := b.s.writeTrackedLink(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *TrackedLinkScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_TrackedLinkScopedCreateBulk                   = TypeScopedCreate
	EntityOf_TrackedLinkScopedCreateBulk                 = "TrackedLink"
	RoleOf_TrackedLinkScopedCreateBulk_Save              = RoleStep
	RoleOf_TrackedLinkScopedCreateBulk_Exec              = RoleStep
	RoleOf_TrackedLinkScopedCreateBulk_OnConflictColumns = RoleStart
)

// ---------------------------------------------------------------- upsert

// TrackedLinkScopedUpsert is the "ON CONFLICT ... DO UPDATE" setter. It cannot move a row to
// another Workspace or point a reference at a value that was not verified on create.
type TrackedLinkScopedUpsert struct{ u *sql.UpdateSet }

const (
	TypeOf_TrackedLinkScopedUpsert   = TypeScopedUpsert
	EntityOf_TrackedLinkScopedUpsert = "TrackedLink"
)

// SetUpdatedAt sets the "updated_at" field.
func (u *TrackedLinkScopedUpsert) SetUpdatedAt(v time.Time) *TrackedLinkScopedUpsert {
	u.u.Set(trackedlink.FieldUpdatedAt, v)
	return u
}

const RoleOf_TrackedLinkScopedUpsert_SetUpdatedAt = RoleStep

// UpdateUpdatedAt sets the "updated_at" field to the value that was provided on create.
func (u *TrackedLinkScopedUpsert) UpdateUpdatedAt() *TrackedLinkScopedUpsert {
	u.u.SetExcluded(trackedlink.FieldUpdatedAt)
	return u
}

const RoleOf_TrackedLinkScopedUpsert_UpdateUpdatedAt = RoleStep

// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *TrackedLinkScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(trackedlink.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// TrackedLinkScopedUpsertOne is the "upsert" of one TrackedLink: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type TrackedLinkScopedUpsertOne struct {
	x        *TrackedLinkScopedCreate
	conflict []sql.ConflictOption
	set      []func(*TrackedLinkUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_TrackedLinkScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_TrackedLinkScopedUpsertOne               = "TrackedLink"
	RoleOf_TrackedLinkScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_TrackedLinkScopedUpsertOne_Ignore          = RoleStep
	RoleOf_TrackedLinkScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_TrackedLinkScopedUpsertOne_Update          = RoleStep
	RoleOf_TrackedLinkScopedUpsertOne_Exec            = RoleStep
	RoleOf_TrackedLinkScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *TrackedLinkScopedCreate) OnConflictColumns(columns ...string) *TrackedLinkScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *TrackedLinkScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *TrackedLinkScopedUpsertOne {
	return &TrackedLinkScopedUpsertOne{x: x, conflict: (&TrackedLinkScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *TrackedLinkScopedUpsertOne) UpdateNewValues() *TrackedLinkScopedUpsertOne {
	u.set = append(u.set, func(r *TrackedLinkUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *TrackedLinkScopedUpsertOne) Ignore() *TrackedLinkScopedUpsertOne {
	u.set = append(u.set, func(r *TrackedLinkUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *TrackedLinkScopedUpsertOne) DoNothing() *TrackedLinkScopedUpsertOne {
	u.set = append(u.set, func(r *TrackedLinkUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *TrackedLinkScopedUpsertOne) Update(set func(*TrackedLinkScopedUpsert)) *TrackedLinkScopedUpsertOne {
	u.set = append(u.set, func(r *TrackedLinkUpsertOne) {
		r.Update(func(s *TrackedLinkUpsert) { set(&TrackedLinkScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *TrackedLinkScopedUpsertOne) build(ctx context.Context, s *Scoped) (*TrackedLinkUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *TrackedLinkScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id.
func (u *TrackedLinkScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	var id int64
	err := u.x.s.writeTrackedLink(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// TrackedLinkScopedUpsertBulk is the "upsert" of several TrackedLink entities.
type TrackedLinkScopedUpsertBulk struct {
	b       *TrackedLinkScopedCreateBulk
	t       *TrackedLinkScoped
	columns []string
	set     []func(*TrackedLinkUpsertBulk)
}

const (
	TypeOf_TrackedLinkScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_TrackedLinkScopedUpsertBulk               = "TrackedLink"
	RoleOf_TrackedLinkScopedUpsertBulk_UpdateNewValues = RoleStep
	RoleOf_TrackedLinkScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_TrackedLinkScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_TrackedLinkScopedUpsertBulk_Update          = RoleStep
	RoleOf_TrackedLinkScopedUpsertBulk_Exec            = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *TrackedLinkScopedCreateBulk) OnConflictColumns(columns ...string) *TrackedLinkScopedUpsertBulk {
	return &TrackedLinkScopedUpsertBulk{b: b, t: &TrackedLinkScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *TrackedLinkScopedUpsertBulk) UpdateNewValues() *TrackedLinkScopedUpsertBulk {
	u.set = append(u.set, func(r *TrackedLinkUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *TrackedLinkScopedUpsertBulk) Ignore() *TrackedLinkScopedUpsertBulk {
	u.set = append(u.set, func(r *TrackedLinkUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *TrackedLinkScopedUpsertBulk) DoNothing() *TrackedLinkScopedUpsertBulk {
	u.set = append(u.set, func(r *TrackedLinkUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *TrackedLinkScopedUpsertBulk) Update(set func(*TrackedLinkScopedUpsert)) *TrackedLinkScopedUpsertBulk {
	u.set = append(u.set, func(r *TrackedLinkUpsertBulk) {
		r.Update(func(s *TrackedLinkUpsert) { set(&TrackedLinkScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *TrackedLinkScopedUpsertBulk) Exec(ctx context.Context) error {
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeTrackedLink(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

// ---------------------------------------------------------------- update

// TrackedLinkScopedUpdateOne updates one TrackedLink. It has no way to move the row to another Workspace: it
// keeps the row's id, its fences and what its setters set, and builds the ent update on the client
// the update runs on.
type TrackedLinkScopedUpdateOne struct {
	s     *Scoped
	id    int64
	where []predicate.TrackedLink
	set   []func(*TrackedLinkUpdateOne)
}

// UpdateOneID updates the TrackedLink with the id; a row of another Workspace is not found.
func (t *TrackedLinkScoped) UpdateOneID(id int64) *TrackedLinkScopedUpdateOne {
	return &TrackedLinkScopedUpdateOne{s: t.s, id: id}
}

// Where appends predicates the row must also match (fencing).
func (x *TrackedLinkScopedUpdateOne) Where(ps ...predicate.TrackedLink) *TrackedLinkScopedUpdateOne {
	x.where = append(x.where, ps...)
	return x
}

// SetUpdatedAt sets the "updated_at" field.
func (x *TrackedLinkScopedUpdateOne) SetUpdatedAt(v time.Time) *TrackedLinkScopedUpdateOne {
	x.set = append(x.set, func(b *TrackedLinkUpdateOne) { b.SetUpdatedAt(v) })
	return x
}

const RoleOf_TrackedLinkScopedUpdateOne_SetUpdatedAt = RoleStep

// Save verifies the references against the Workspace, then updates the TrackedLink.
func (x *TrackedLinkScopedUpdateOne) Save(ctx context.Context) (*TrackedLink, error) {
	return x.save(ctx, "update", skipUnchanged)
}

// build makes the ent update on the client of s and verifies the references it sets.
func (x *TrackedLinkScopedUpdateOne) build(ctx context.Context, s *Scoped) (*TrackedLinkUpdateOne, error) {
	b := s.c.TrackedLink.UpdateOneID(x.id).Where(s.inTrackedLink(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkTrackedLink(ctx, b.Mutation()))
}

// save is Save under a verb, doing with an unchanged row what unchanged says.
func (x *TrackedLinkScopedUpdateOne) save(ctx context.Context, verb string, unchanged unchangedRows) (*TrackedLink, error) {
	where := x.s.inTrackedLink(x.where...)
	var updated *TrackedLink
	err := x.s.writeTrackedLink(ctx, verb, append([]predicate.TrackedLink{trackedlink.ID(x.id)}, where...), unchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		updated, err = b.Save(ctx)
		return nil, err
	})
	return written(updated, err)
}

// Exec is like Save, discarding the entity.
func (x *TrackedLinkScopedUpdateOne) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_TrackedLinkScopedUpdateOne       = TypeScopedUpdate
	EntityOf_TrackedLinkScopedUpdateOne     = "TrackedLink"
	RoleOf_TrackedLinkScopedUpdateOne_Where = RoleStep
	RoleOf_TrackedLinkScopedUpdateOne_Save  = RoleStep
	RoleOf_TrackedLinkScopedUpdateOne_Exec  = RoleStep
)

// TrackedLinkScopedUpdate is a conditional bulk update of one Workspace: it keeps its predicates and
// what its setters and modifiers set, and builds the ent update on the client the update runs on.
type TrackedLinkScopedUpdate struct {
	s     *Scoped
	where []predicate.TrackedLink
	set   []func(*TrackedLinkUpdate)
	// modErr is set when a Modify modifier tried to assign workspace_id.
	modErr error
}

// Update updates the TrackedLink entities of the Workspace that match the predicates.
func (t *TrackedLinkScoped) Update() *TrackedLinkScopedUpdate {
	return &TrackedLinkScopedUpdate{s: t.s}
}

// Where appends predicates the rows must match.
func (x *TrackedLinkScopedUpdate) Where(ps ...predicate.TrackedLink) *TrackedLinkScopedUpdate {
	x.where = append(x.where, ps...)
	return x
}

// Modify adds a statement modifier for computed assignments the typed setters cannot
// express (SET col = LEAST(col + ..., ...)). A modifier gets assignment-only access
// (ScopedAssign), so it cannot widen the Workspace predicate; an assignment to
// workspace_id is refused: each modifier is probed against a scratch statement here, and
// Save fails with ErrWorkspaceAssign.
func (x *TrackedLinkScopedUpdate) Modify(modifiers ...func(a *ScopedAssign)) *TrackedLinkScopedUpdate {
	for _, m := range modifiers {
		probe := &ScopedAssign{u: sql.Update(trackedlink.Table)}
		m(probe)
		if probe.workspace {
			x.modErr = ErrWorkspaceAssign
		}
		x.set = append(x.set, func(b *TrackedLinkUpdate) {
			b.Modify(func(u *sql.UpdateBuilder) { m(&ScopedAssign{u: u}) })
		})
	}
	return x
}

// SetUpdatedAt sets the "updated_at" field.
func (x *TrackedLinkScopedUpdate) SetUpdatedAt(v time.Time) *TrackedLinkScopedUpdate {
	x.set = append(x.set, func(b *TrackedLinkUpdate) { b.SetUpdatedAt(v) })
	return x
}

const RoleOf_TrackedLinkScopedUpdate_SetUpdatedAt = RoleStep

// build makes the ent update on the client of s and verifies the references it sets.
func (x *TrackedLinkScopedUpdate) build(ctx context.Context, s *Scoped) (*TrackedLinkUpdate, error) {
	b := s.c.TrackedLink.Update().Where(s.inTrackedLink(x.where...)...)
	for _, set := range x.set {
		set(b)
	}
	return written(b, s.checkTrackedLink(ctx, b.Mutation()))
}

// Save verifies the references against the Workspace, then updates the rows and
// returns how many changed.
func (x *TrackedLinkScopedUpdate) Save(ctx context.Context) (int, error) {
	if x.modErr != nil {
		return 0, x.modErr
	}
	where := x.s.inTrackedLink(x.where...)
	var n int
	err := x.s.writeTrackedLink(ctx, "update", where, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		n, err = b.Save(ctx)
		return nil, err
	})
	return written(n, err)
}

// Exec is like Save, discarding the count.
func (x *TrackedLinkScopedUpdate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

const (
	TypeOf_TrackedLinkScopedUpdate        = TypeScopedUpdate
	EntityOf_TrackedLinkScopedUpdate      = "TrackedLink"
	RoleOf_TrackedLinkScopedUpdate_Where  = RoleStep
	RoleOf_TrackedLinkScopedUpdate_Modify = RoleStep
	RoleOf_TrackedLinkScopedUpdate_Save   = RoleStep
	RoleOf_TrackedLinkScopedUpdate_Exec   = RoleStep
)

