// TrackingDomain returns the TrackingDomain entities of the Workspace.
func (s *Scoped) TrackingDomain() *TrackingDomainScoped { return &TrackingDomainScoped{s: s} }

const (
	TypeOf_TrackingDomainScoped             = TypeWrapper
	EntityOf_TrackingDomainScoped           = "TrackingDomain"
	RoleOf_Scoped_TrackingDomain            = RoleNone
	RoleOf_TrackingDomainScoped_Query       = RoleRead
	RoleOf_TrackingDomainScoped_Get         = RoleRead
	RoleOf_TrackingDomainScoped_DeleteOneID = RoleStart
	RoleOf_TrackingDomainScoped_UpdateOneID = RoleStart
	RoleOf_TrackingDomainScoped_Delete      = RoleStart
	RoleOf_TrackingDomainScoped_Create      = RoleStart
	RoleOf_TrackingDomainScoped_CreateBulk  = RoleStart
	RoleOf_TrackingDomainScoped_Update      = RoleStart
)

// inTrackingDomain confines predicates of TrackingDomain rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inTrackingDomain(ps ...predicate.TrackingDomain) []predicate.TrackingDomain {
	return append([]predicate.TrackingDomain{trackingdomain.WorkspaceID(s.ws)}, ps...)
}

// Query returns a TrackingDomain query already confined to the Workspace.
func (t *TrackingDomainScoped) Query() *TrackingDomainQuery {
	return t.s.c.TrackingDomain.Query().Where(t.s.inTrackingDomain()...)
}

// Get returns the TrackingDomain with the id; a row of another Workspace is not found.
func (t *TrackingDomainScoped) Get(ctx context.Context, id int64) (*TrackingDomain, error) {
	return t.Query().Where(trackingdomain.ID(id)).Only(ctx)
}

// writeTrackingDomain runs a write of TrackingDomain rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeTrackingDomain(ctx context.Context, verb string, where []predicate.TrackingDomain, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*TrackingDomain
			if where != nil {
				var err error
				if before, err = ts.c.TrackingDomain.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*TrackingDomain, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.TrackingDomain.Query().Where(trackingdomain.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*TrackingDomain, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeTrackingDomain(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

// checkTrackingDomain verifies every reference the mutations set against the Workspace of s, one query per
// reference for all of them.
func (s *Scoped) checkTrackingDomain(ctx context.Context, ms ...*TrackingDomainMutation) error {
	return nil
}

