// Save verifies the references against the Workspace, then creates the TrackingDomain.
func (x *TrackingDomainScopedCreate) Save(ctx context.Context) (*TrackingDomain, error) {
	var created *TrackingDomain
	err := x.s.writeTrackingDomain(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *TrackingDomainScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// TrackingDomainScopedCreateBulk creates several TrackingDomain entities of one Workspace at once.
type TrackingDomainScopedCreateBulk struct {
	s  *Scoped
	xs []*TrackingDomainScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *TrackingDomainScoped) CreateBulk(xs ...*TrackingDomainScopedCreate) *TrackingDomainScopedCreateBulk {
	return &TrackingDomainScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *TrackingDomainScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("TrackingDomain: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *TrackingDomainScopedCreateBulk) build(ctx context.Context, s *Scoped) (*TrackingDomainCreateBulk, error) {
	builders := make([]*TrackingDomainCreate, len(b.xs))
	ms := make([]*TrackingDomainMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkTrackingDomain(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.TrackingDomain.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the TrackingDomain entities.
func (b *TrackingDomainScopedCreateBulk) Save(ctx context.Context) ([]*TrackingDomain, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*TrackingDomain
	err := b.s.writeTrackingDomain(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *TrackingDomainScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

