// Save verifies the references against the Workspace, then creates the Unsubscribe.
func (x *UnsubscribeScopedCreate) Save(ctx context.Context) (*Unsubscribe, error) {
	var created *Unsubscribe
	err := x.s.writeUnsubscribe(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *UnsubscribeScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// UnsubscribeScopedCreateBulk creates several Unsubscribe entities of one Workspace at once.
type UnsubscribeScopedCreateBulk struct {
	s  *Scoped
	xs []*UnsubscribeScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *UnsubscribeScoped) CreateBulk(xs ...*UnsubscribeScopedCreate) *UnsubscribeScopedCreateBulk {
	return &UnsubscribeScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *UnsubscribeScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Unsubscribe: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *UnsubscribeScopedCreateBulk) build(ctx context.Context, s *Scoped) (*UnsubscribeCreateBulk, error) {
	builders := make([]*UnsubscribeCreate, len(b.xs))
	ms := make([]*UnsubscribeMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkUnsubscribe(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Unsubscribe.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Unsubscribe entities.
func (b *UnsubscribeScopedCreateBulk) Save(ctx context.Context) ([]*Unsubscribe, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Unsubscribe
	err := b.s.writeUnsubscribe(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *UnsubscribeScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

const (
	TypeOf_UnsubscribeScopedCreateBulk                   = TypeScopedCreate
	EntityOf_UnsubscribeScopedCreateBulk                 = "Unsubscribe"
	RoleOf_UnsubscribeScopedCreateBulk_Save              = RoleStep
	RoleOf_UnsubscribeScopedCreateBulk_Exec              = RoleStep
	RoleOf_UnsubscribeScopedCreateBulk_OnConflictColumns = RoleStart
)

