// Save verifies the references against the Workspace, then creates the Usage.
func (x *UsageScopedCreate) Save(ctx context.Context) (*Usage, error) {
	var created *Usage
	err := x.s.writeUsage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *UsageScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// UsageScopedCreateBulk creates several Usage entities of one Workspace at once.
type UsageScopedCreateBulk struct {
	s  *Scoped
	xs []*UsageScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *UsageScoped) CreateBulk(xs ...*UsageScopedCreate) *UsageScopedCreateBulk {
	return &UsageScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *UsageScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Usage: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *UsageScopedCreateBulk) build(ctx context.Context, s *Scoped) (*UsageCreateBulk, error) {
	builders := make([]*UsageCreate, len(b.xs))
	ms := make([]*UsageMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkUsage(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Usage.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Usage entities.
func (b *UsageScopedCreateBulk) Save(ctx context.Context) ([]*Usage, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Usage
	err := b.s.writeUsage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *UsageScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

