// conflictOptions confines the DO UPDATE part to rows of the Workspace.
// target, when not nil, is the predicate of a partial unique index the conflict is inferred from.
func (t *UsageScoped) conflictOptions(columns []string, target *sql.Predicate) []sql.ConflictOption {
	opts := []sql.ConflictOption{
		sql.ConflictColumns(columns...),
		sql.UpdateWhere(sql.EQ(usage.FieldWorkspaceID, t.s.ws)),
	}
	if target != nil {
		opts = append(opts, sql.ConflictWhere(target))
	}
	return opts
}

// UsageScopedUpsertOne is the "upsert" of one Usage: the create it was started on, which a setter
// called later still changes, and what to do on a conflict.
type UsageScopedUpsertOne struct {
	x        *UsageScopedCreate
	conflict []sql.ConflictOption
	set      []func(*UsageUpsertOne)
	// doNothing: the conflict action is DO NOTHING (the only upsert an audited entity allows).
	doNothing bool
}

const (
	TypeOf_UsageScopedUpsertOne                 = TypeScopedUpsert
	EntityOf_UsageScopedUpsertOne               = "Usage"
	RoleOf_UsageScopedUpsertOne_UpdateNewValues = RoleStep
	RoleOf_UsageScopedUpsertOne_Ignore          = RoleStep
	RoleOf_UsageScopedUpsertOne_DoNothing       = RoleStep
	RoleOf_UsageScopedUpsertOne_Update          = RoleStep
	RoleOf_UsageScopedUpsertOne_Exec            = RoleStep
	RoleOf_UsageScopedUpsertOne_ID              = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *UsageScopedCreate) OnConflictColumns(columns ...string) *UsageScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *UsageScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *UsageScopedUpsertOne {
	return &UsageScopedUpsertOne{x: x, conflict: (&UsageScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *UsageScopedUpsertOne) UpdateNewValues() *UsageScopedUpsertOne {
	u.set = append(u.set, func(r *UsageUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *UsageScopedUpsertOne) Ignore() *UsageScopedUpsertOne {
	u.set = append(u.set, func(r *UsageUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *UsageScopedUpsertOne) DoNothing() *UsageScopedUpsertOne {
	u.set = append(u.set, func(r *UsageUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *UsageScopedUpsertOne) Update(set func(*UsageScopedUpsert)) *UsageScopedUpsertOne {
	u.set = append(u.set, func(r *UsageUpsertOne) {
		r.Update(func(s *UsageUpsert) { set(&UsageScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *UsageScopedUpsertOne) build(ctx context.Context, s *Scoped) (*UsageUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *UsageScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id.
func (u *UsageScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	var id int64
	err := u.x.s.writeUsage(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

