// Save verifies the references against the Workspace, then creates the Visitor.
func (x *VisitorScopedCreate) Save(ctx context.Context) (*Visitor, error) {
	var created *Visitor
	err := x.s.writeVisitor(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *VisitorScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// VisitorScopedCreateBulk creates several Visitor entities of one Workspace at once.
type VisitorScopedCreateBulk struct {
	s  *Scoped
	xs []*VisitorScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *VisitorScoped) CreateBulk(xs ...*VisitorScopedCreate) *VisitorScopedCreateBulk {
	return &VisitorScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *VisitorScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("Visitor: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *VisitorScopedCreateBulk) build(ctx context.Context, s *Scoped) (*VisitorCreateBulk, error) {
	builders := make([]*VisitorCreate, len(b.xs))
	ms := make([]*VisitorMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkVisitor(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.Visitor.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the Visitor entities.
func (b *VisitorScopedCreateBulk) Save(ctx context.Context) ([]*Visitor, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*Visitor
	err := b.s.writeVisitor(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		return nil, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *VisitorScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

