// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (x *VisitorScopedCreate) OnConflictColumns(columns ...string) *VisitorScopedUpsertOne {
	return x.OnConflictColumnsWhere(nil, columns...)
}

// OnConflictColumnsWhere is OnConflictColumns for a partial unique index: target is the
// index's predicate, which Postgres needs to infer the index from the columns.
func (x *VisitorScopedCreate) OnConflictColumnsWhere(target *sql.Predicate, columns ...string) *VisitorScopedUpsertOne {
	return &VisitorScopedUpsertOne{x: x, conflict: (&VisitorScoped{s: x.s}).conflictOptions(columns, target)}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *VisitorScopedUpsertOne) UpdateNewValues() *VisitorScopedUpsertOne {
	u.set = append(u.set, func(r *VisitorUpsertOne) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *VisitorScopedUpsertOne) Ignore() *VisitorScopedUpsertOne {
	u.set = append(u.set, func(r *VisitorUpsertOne) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *VisitorScopedUpsertOne) DoNothing() *VisitorScopedUpsertOne {
	u.set = append(u.set, func(r *VisitorUpsertOne) { r.DoNothing() })
	u.doNothing = true
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *VisitorScopedUpsertOne) Update(set func(*VisitorScopedUpsert)) *VisitorScopedUpsertOne {
	u.set = append(u.set, func(r *VisitorUpsertOne) {
		r.Update(func(s *VisitorUpsert) { set(&VisitorScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// build makes the ent upsert on the client of s and verifies the create's references.
func (u *VisitorScopedUpsertOne) build(ctx context.Context, s *Scoped) (*VisitorUpsertOne, error) {
	b, err := u.x.build(ctx, s)
	if err != nil {
		return nil, err
	}
	r := b.OnConflict(u.conflict...)
	for _, set := range u.set {
		set(r)
	}
	return r, nil
}

// Exec verifies the references, then executes the upsert.
func (u *VisitorScopedUpsertOne) Exec(ctx context.Context) error {
	_, err := u.ID(ctx)
	return err
}

// ID is like Exec, returning the inserted or updated id.
func (u *VisitorScopedUpsertOne) ID(ctx context.Context) (int64, error) {
	var id int64
	err := u.x.s.writeVisitor(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		r, err := u.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if id, err = r.ID(ctx); err != nil {
			return nil, err
		}
		return []int64{id}, nil
	})
	return written(id, err)
}

// VisitorScopedUpsertBulk is the "upsert" of several Visitor entities.
type VisitorScopedUpsertBulk struct {
	b       *VisitorScopedCreateBulk
	t       *VisitorScoped
	columns []string
	set     []func(*VisitorUpsertBulk)
}

const (
	TypeOf_VisitorScopedUpsertBulk                 = TypeScopedUpsert
	EntityOf_VisitorScopedUpsertBulk               = "Visitor"
	RoleOf_VisitorScopedUpsertBulk_UpdateNewValues = RoleStep
	RoleOf_VisitorScopedUpsertBulk_Ignore          = RoleStep
	RoleOf_VisitorScopedUpsertBulk_DoNothing       = RoleStep
	RoleOf_VisitorScopedUpsertBulk_Update          = RoleStep
	RoleOf_VisitorScopedUpsertBulk_Exec            = RoleStep
)

// OnConflictColumns configures the columns as conflict target. A conflicting row of
// another Workspace is never updated.
func (b *VisitorScopedCreateBulk) OnConflictColumns(columns ...string) *VisitorScopedUpsertBulk {
	return &VisitorScopedUpsertBulk{b: b, t: &VisitorScoped{s: b.s}, columns: columns}
}

// UpdateNewValues updates the mutable fields using the new values set on create.
func (u *VisitorScopedUpsertBulk) UpdateNewValues() *VisitorScopedUpsertBulk {
	u.set = append(u.set, func(r *VisitorUpsertBulk) { r.UpdateNewValues() })
	return u
}

// Ignore sets each column to itself in case of conflict.
func (u *VisitorScopedUpsertBulk) Ignore() *VisitorScopedUpsertBulk {
	u.set = append(u.set, func(r *VisitorUpsertBulk) { r.Ignore() })
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
func (u *VisitorScopedUpsertBulk) DoNothing() *VisitorScopedUpsertBulk {
	u.set = append(u.set, func(r *VisitorUpsertBulk) { r.DoNothing() })
	return u
}

// Update overrides fields' `UPDATE` values.
func (u *VisitorScopedUpsertBulk) Update(set func(*VisitorScopedUpsert)) *VisitorScopedUpsertBulk {
	u.set = append(u.set, func(r *VisitorUpsertBulk) {
		r.Update(func(s *VisitorUpsert) { set(&VisitorScopedUpsert{u: s.UpdateSet}) })
	})
	return u
}

// Exec verifies every builder's references, then executes the upsert.
func (u *VisitorScopedUpsertBulk) Exec(ctx context.Context) error {
	if err := u.b.refuseForeign(); err != nil {
		return err
	}
	return u.b.s.writeVisitor(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := u.b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		r := raw.OnConflict(u.t.conflictOptions(u.columns, nil)...)
		for _, set := range u.set {
			set(r)
		}
		return nil, r.Exec(ctx)
	})
}

