// inWebhookEndpoint confines predicates of WebhookEndpoint rows to the Workspace of s: every read and write of
// them goes through it.
func (s *Scoped) inWebhookEndpoint(ps ...predicate.WebhookEndpoint) []predicate.WebhookEndpoint {
	return append([]predicate.WebhookEndpoint{webhookendpoint.WorkspaceID(s.ws)}, ps...)
}

// Query returns a WebhookEndpoint query already confined to the Workspace.
func (t *WebhookEndpointScoped) Query() *WebhookEndpointQuery {
	return t.s.c.WebhookEndpoint.Query().Where(t.s.inWebhookEndpoint()...)
}

// Get returns the WebhookEndpoint with the id; a row of another Workspace is not found.
func (t *WebhookEndpointScoped) Get(ctx context.Context, id int64) (*WebhookEndpoint, error) {
	return t.Query().Where(webhookendpoint.ID(id)).Only(ctx)
}

// writeWebhookEndpoint runs a write of WebhookEndpoint rows: run builds it on the client of the scope it is
// given and executes it, and reaches no other client. Through an audited scope (Scoped.As)
// that scope is bound to the transaction that carries the write's Audit entries (ADR 0022), which it
// joins or opens: the rows where matches are read before the write, then the same rows and the ones
// run reports it created after it, and verb is recorded for each of them whose audited fields
// changed, or for every one of them when unchanged is recordUnchanged. Through any other scope run gets the scope itself.
func (s *Scoped) writeWebhookEndpoint(ctx context.Context, verb string, where []predicate.WebhookEndpoint, unchanged unchangedRows, run func(s *Scoped) ([]int64, error)) error {
	if s.auditing() {
		return s.audited(ctx, func(ts *Scoped) error {
			var before []*WebhookEndpoint
			if where != nil {
				var err error
				if before, err = ts.c.WebhookEndpoint.Query().Where(where...).All(ctx); err != nil {
					return err
				}
			}
			created, err := run(ts)
			if err != nil {
				return err
			}
			ids := make([]int64, 0, len(before)+len(created))
			beforeByID := make(map[int64]*WebhookEndpoint, len(before))
			for _, row := range before {
				ids = append(ids, row.ID)
				beforeByID[row.ID] = row
			}
			ids = append(ids, created...)
			after, err := ts.c.WebhookEndpoint.Query().Where(webhookendpoint.IDIn(ids...)).All(ctx)
			if err != nil {
				return err
			}
			afterByID := make(map[int64]*WebhookEndpoint, len(after))
			for _, row := range after {
				afterByID[row.ID] = row
			}
			for _, id := range ids {
				if beforeByID[id] == nil && afterByID[id] == nil {
					continue
				}
				if change, changed := auditChangeWebhookEndpoint(verb, beforeByID[id], afterByID[id]); changed || unchanged == recordUnchanged {
					if err := ts.record(ctx, change); err != nil {
						return err
					}
				}
			}
			return nil
		})
	}
	_, err := run(s)
	return err
}

