// Save verifies the references against the Workspace, then creates the WebhookEndpoint.
func (x *WebhookEndpointScopedCreate) Save(ctx context.Context) (*WebhookEndpoint, error) {
	var created *WebhookEndpoint
	err := x.s.writeWebhookEndpoint(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		b, err := x.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = b.Save(ctx); err != nil {
			return nil, err
		}
		return []int64{created.ID}, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entity.
func (x *WebhookEndpointScopedCreate) Exec(ctx context.Context) error {
	_, err := x.Save(ctx)
	return err
}

// ---------------------------------------------------------------- create bulk

// WebhookEndpointScopedCreateBulk creates several WebhookEndpoint entities of one Workspace at once.
type WebhookEndpointScopedCreateBulk struct {
	s  *Scoped
	xs []*WebhookEndpointScopedCreate
}

// CreateBulk batches creates started on this Workspace.
func (t *WebhookEndpointScoped) CreateBulk(xs ...*WebhookEndpointScopedCreate) *WebhookEndpointScopedCreateBulk {
	return &WebhookEndpointScopedCreateBulk{s: t.s, xs: xs}
}

// refuseForeign refuses a create started on another Workspace's scope.
func (b *WebhookEndpointScopedCreateBulk) refuseForeign() error {
	for _, x := range b.xs {
		if x.s.ws != b.s.ws {
			return fmt.Errorf("WebhookEndpoint: builder of another scope: %w", ErrNotInWorkspace)
		}
	}
	return nil
}

// build makes the ent bulk create on the client of s, every create of it in the Workspace, and
// verifies the references of all of them, one query per reference rather than one per row.
func (b *WebhookEndpointScopedCreateBulk) build(ctx context.Context, s *Scoped) (*WebhookEndpointCreateBulk, error) {
	builders := make([]*WebhookEndpointCreate, len(b.xs))
	ms := make([]*WebhookEndpointMutation, len(b.xs))
	for i, x := range b.xs {
		builders[i] = x.raw(s)
		ms[i] = builders[i].Mutation()
	}
	if err := s.checkWebhookEndpoint(ctx, ms...); err != nil {
		return nil, err
	}
	return s.c.WebhookEndpoint.CreateBulk(builders...), nil
}

// Save verifies every builder's references, then creates the WebhookEndpoint entities.
func (b *WebhookEndpointScopedCreateBulk) Save(ctx context.Context) ([]*WebhookEndpoint, error) {
	if err := b.refuseForeign(); err != nil {
		return nil, err
	}
	var created []*WebhookEndpoint
	err := b.s.writeWebhookEndpoint(ctx, "create", nil, skipUnchanged, func(s *Scoped) ([]int64, error) {
		raw, err := b.build(ctx, s)
		if err != nil {
			return nil, err
		}
		if created, err = raw.Save(ctx); err != nil {
			return nil, err
		}
		ids := make([]int64, len(created))
		for i, row := range created {
			ids[i] = row.ID
		}
		return ids, nil
	})
	return written(created, err)
}

// Exec is like Save, discarding the entities.
func (b *WebhookEndpointScopedCreateBulk) Exec(ctx context.Context) error {
	_, err := b.Save(ctx)
	return err
}

